from __future__ import annotations

import contextlib
import ctypes
import subprocess
import sys
import unittest
import warnings
from pathlib import Path

import numpy as np

from compat.cnumpy_ctypes import CnumpyError, CnumpyRuntime


ROOT = Path(__file__).resolve().parents[2]
DLL = ROOT / "build" / "x64" / "Release" / "cnumpy_ahk.dll"


class DtypeMetadataSemanticsTests(unittest.TestCase):
    _REPRESENTED_TYPES = (
        (1, np.dtype(np.bool_)),
        (2, np.dtype(np.int8)),
        (3, np.dtype(np.uint8)),
        (4, np.dtype(np.int16)),
        (5, np.dtype(np.uint16)),
        (6, np.dtype(np.int32)),
        (7, np.dtype(np.uint32)),
        (8, np.dtype(np.int64)),
        (9, np.dtype(np.uint64)),
        (10, np.dtype(np.int64)),
        (11, np.dtype(np.uint64)),
        (12, np.dtype(np.float32)),
        (13, np.dtype(np.float64)),
        (14, np.dtype(np.longdouble)),
        (15, np.dtype(np.complex64)),
        (16, np.dtype(np.complex128)),
        (17, np.dtype(np.clongdouble)),
        (18, np.dtype(np.object_)),
        (19, np.dtype("S0")),
        (20, np.dtype("U0")),
        (21, np.dtype("V0")),
        (22, np.dtype("datetime64")),
        (23, np.dtype("timedelta64")),
        (24, np.dtype(np.float16)),
    )

    @staticmethod
    def _functions(runtime: CnumpyRuntime):
        itemsize = runtime.dll.cnp_dtype_itemsize
        itemsize.argtypes = [ctypes.c_int]
        itemsize.restype = ctypes.c_int
        kind = runtime.dll.cnp_dtype_kind
        kind.argtypes = [ctypes.c_int]
        kind.restype = ctypes.c_char
        return itemsize, kind

    def test_itemsize_and_kind_match_numpy_125_represented_storage(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            itemsize, kind = self._functions(runtime)
            for dtype_number, numpy_dtype in self._REPRESENTED_TYPES:
                with self.subTest(
                    dtype_number=dtype_number, dtype=str(numpy_dtype)
                ):
                    runtime.dll.cnp_clear_error()
                    self.assertEqual(numpy_dtype.itemsize, itemsize(dtype_number))
                    self.assertEqual(numpy_dtype.kind, kind(dtype_number).decode())
                    self.assertEqual(0, runtime.error_state().status)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_invalid_dtype_metadata_queries_surface_native_type_errors(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            itemsize, kind = self._functions(runtime)
            for dtype_number in (-1, 0, 25):
                with self.subTest(api="itemsize", dtype=dtype_number):
                    runtime.dll.cnp_clear_error()
                    self.assertEqual(0, itemsize(dtype_number))
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual("cnp_dtype_itemsize", error.function)
                    self.assertIn("valid CNP_TYPE", error.message)
                with self.subTest(api="kind", dtype=dtype_number):
                    runtime.dll.cnp_clear_error()
                    self.assertEqual(b"\0", kind(dtype_number))
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual("cnp_dtype_kind", error.function)
                    self.assertIn("valid CNP_TYPE", error.message)

            runtime.dll.cnp_clear_error()
            self.assertEqual(np.dtype(np.float64).itemsize, itemsize(13))
            self.assertEqual(0, runtime.error_state().status)
            self.assertEqual(baseline, runtime.retained_bytes)


class PromotionSemanticsTests(unittest.TestCase):
    _REPRESENTED_TYPES = DtypeMetadataSemanticsTests._REPRESENTED_TYPES
    _NUMPY_BY_CNP = dict(_REPRESENTED_TYPES)
    _CATEGORY_ONLY_KINDS = frozenset("OSUVMm")

    @staticmethod
    def _promote_function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_promote_types_public
        function.argtypes = [ctypes.c_int, ctypes.c_int]
        function.restype = ctypes.c_int
        return function

    @staticmethod
    def _result_type_function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_result_type
        function.argtypes = [
            ctypes.c_int,
            ctypes.POINTER(ctypes.c_void_p),
        ]
        function.restype = ctypes.c_int
        return function

    @classmethod
    def _assert_result_matches_numpy(
        cls, actual_type: int, expected: np.dtype
    ) -> None:
        cls_dtype = cls._NUMPY_BY_CNP.get(actual_type)
        if cls_dtype is None:
            raise AssertionError(f"unexpected CNP_TYPE result: {actual_type}")
        if expected.kind in cls._CATEGORY_ONLY_KINDS:
            if cls_dtype.kind != expected.kind:
                raise AssertionError(
                    f"expected dtype category {expected.kind!r}, "
                    f"got {cls_dtype.kind!r} from CNP_TYPE {actual_type}"
                )
        else:
            np.testing.assert_equal(cls_dtype, expected)

    def test_pairwise_promotions_match_numpy_125_for_every_represented_type(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._promote_function(runtime)
            for left_type, left_dtype in self._REPRESENTED_TYPES:
                for right_type, right_dtype in self._REPRESENTED_TYPES:
                    with self.subTest(
                        left_type=left_type,
                        right_type=right_type,
                        left_dtype=str(left_dtype),
                        right_dtype=str(right_dtype),
                    ):
                        try:
                            expected = np.promote_types(
                                left_dtype, right_dtype
                            )
                        except np.exceptions.DTypePromotionError:
                            expected = None
                        runtime.dll.cnp_clear_error()
                        actual_type = function(left_type, right_type)
                        error = runtime.error_state()
                        if expected is None:
                            self.assertEqual(0, actual_type)
                            self.assertEqual(-3, error.status)
                            self.assertEqual(
                                "cnp_promote_types_public", error.function
                            )
                            self.assertIn("common dtype", error.message)
                        else:
                            self.assertNotEqual(0, actual_type)
                            self.assertEqual(0, error.status)
                            self._assert_result_matches_numpy(
                                actual_type, expected
                            )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_dtype_result_type_alias_matches_the_pairwise_promotion_table(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = runtime.dll.cnp_dtype_result_type
            function.argtypes = [ctypes.c_int, ctypes.c_int]
            function.restype = ctypes.c_int
            for left_type, left_dtype in self._REPRESENTED_TYPES:
                for right_type, right_dtype in self._REPRESENTED_TYPES:
                    with self.subTest(
                        left_type=left_type, right_type=right_type
                    ):
                        try:
                            expected = np.promote_types(
                                left_dtype, right_dtype
                            )
                        except np.exceptions.DTypePromotionError:
                            expected = None
                        runtime.dll.cnp_clear_error()
                        actual_type = function(left_type, right_type)
                        error = runtime.error_state()
                        if expected is None:
                            self.assertEqual(0, actual_type)
                            self.assertEqual(-3, error.status)
                            self.assertEqual(
                                "cnp_dtype_result_type", error.function
                            )
                            self.assertIn("common dtype", error.message)
                        else:
                            self.assertEqual(0, error.status)
                            self._assert_result_matches_numpy(
                                actual_type, expected
                            )

            for left_type, right_type in ((-1, 1), (0, 1), (1, 25)):
                with self.subTest(
                    left_type=left_type, right_type=right_type
                ):
                    runtime.dll.cnp_clear_error()
                    self.assertEqual(0, function(left_type, right_type))
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual(
                        "cnp_dtype_result_type", error.function
                    )
                    self.assertIn("valid CNP_TYPE", error.message)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_result_type_matches_numpy_125_for_array_dtype_sequences(
        self,
    ) -> None:
        cases = (
            (1,),
            (2, 3, 24),
            (9, 8),
            (8, 10, 12),
            (12, 15),
            (22, 23),
            (23, 6),
            (18, 21),
            (23, 9),
        )
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            result_type = self._result_type_function(runtime)
            array_new = runtime.dll.cnp_array_new
            array_new.argtypes = [
                ctypes.c_int,
                ctypes.POINTER(ctypes.c_int64),
                ctypes.c_int,
                ctypes.c_int,
            ]
            array_new.restype = ctypes.c_void_p
            shape = (ctypes.c_int64 * 1)(1)
            for dtype_numbers in cases:
                arrays = []
                try:
                    for dtype_number in dtype_numbers:
                        runtime.dll.cnp_clear_error()
                        pointer = array_new(1, shape, dtype_number, 0)
                        arrays.append(
                            runtime._owned_result(pointer, "cnp_array_new")
                        )
                    pointers = (ctypes.c_void_p * len(arrays))(
                        *(array.pointer.value for array in arrays)
                    )
                    numpy_arrays = tuple(
                        np.empty(
                            (1,), dtype=self._NUMPY_BY_CNP[dtype_number]
                        )
                        for dtype_number in dtype_numbers
                    )
                    try:
                        expected = np.result_type(*numpy_arrays)
                    except np.exceptions.DTypePromotionError:
                        expected = None
                    runtime.dll.cnp_clear_error()
                    actual_type = result_type(len(arrays), pointers)
                    error = runtime.error_state()
                    with self.subTest(dtype_numbers=dtype_numbers):
                        if expected is None:
                            self.assertEqual(0, actual_type)
                            self.assertEqual(-3, error.status)
                            self.assertEqual("cnp_result_type", error.function)
                            self.assertIn("common dtype", error.message)
                        else:
                            self.assertNotEqual(0, actual_type)
                            self.assertEqual(0, error.status)
                            self._assert_result_matches_numpy(
                                actual_type, expected
                            )
                finally:
                    for array in reversed(arrays):
                        array.close()
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_result_type_applies_numpy_125_scalar_value_rules(
        self,
    ) -> None:
        cases = (
            (np.asarray(5, dtype=np.int16), np.dtype(np.int8)),
            (np.asarray(127, dtype=np.int64), np.dtype(np.int8)),
            (np.asarray(128, dtype=np.int64), np.dtype(np.int8)),
            (np.asarray(-129, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(-128, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(-1, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(0, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(255, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(256, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(65535, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(65536, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(2**32 - 1, dtype=np.int64), np.dtype(np.float16)),
            (np.asarray(2**32, dtype=np.int64), np.dtype(np.float16)),
            (
                np.asarray(np.iinfo(np.int64).max, dtype=np.int64),
                np.dtype(np.float16),
            ),
            (np.asarray(0, dtype=np.uint64), np.dtype(np.int64)),
            (np.asarray(255, dtype=np.uint64), np.dtype(np.float16)),
            (np.asarray(256, dtype=np.uint64), np.dtype(np.float16)),
            (np.asarray(2**32, dtype=np.uint64), np.dtype(np.float16)),
            (
                np.asarray(np.iinfo(np.uint64).max, dtype=np.uint64),
                np.dtype(np.int64),
            ),
            (np.asarray(0.0, dtype=np.float64), np.dtype(np.float32)),
            (np.asarray(1.5, dtype=np.float64), np.dtype(np.float32)),
            (np.asarray(64999.0, dtype=np.float64), np.dtype(np.float32)),
            (np.asarray(65000.0, dtype=np.float64), np.dtype(np.float32)),
            (
                np.asarray(np.finfo(np.float32).max, dtype=np.float64),
                np.dtype(np.float32),
            ),
            (
                np.asarray(
                    np.nextafter(
                        np.float64(np.finfo(np.float32).max), np.inf
                    ),
                    dtype=np.float64,
                ),
                np.dtype(np.float32),
            ),
            (np.asarray(1e100, dtype=np.float64), np.dtype(np.float32)),
            (np.asarray(np.inf, dtype=np.float64), np.dtype(np.float32)),
            (np.asarray(np.nan, dtype=np.float64), np.dtype(np.float32)),
            (
                np.asarray(1 + 2j, dtype=np.complex128),
                np.dtype(np.complex64),
            ),
            (
                np.asarray(
                    complex(np.finfo(np.float32).max, 0.0),
                    dtype=np.complex128,
                ),
                np.dtype(np.complex64),
            ),
            (
                np.asarray(complex(1e100, 2.0), dtype=np.complex128),
                np.dtype(np.complex64),
            ),
        )
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            result_type = self._result_type_function(runtime)
            for scalar, array_dtype in cases:
                values = np.zeros((1,), dtype=array_dtype)
                with self.subTest(
                    scalar_dtype=str(scalar.dtype),
                    scalar_value=scalar.item(),
                    array_dtype=str(array_dtype),
                ), runtime.from_numpy(scalar) as native_scalar, runtime.from_numpy(
                    values
                ) as native_array:
                    pointers = (ctypes.c_void_p * 2)(
                        native_scalar.pointer.value,
                        native_array.pointer.value,
                    )
                    expected = np.result_type(scalar, values)
                    runtime.dll.cnp_clear_error()
                    actual_type = result_type(2, pointers)
                    self.assertEqual(0, runtime.error_state().status)
                    self._assert_result_matches_numpy(actual_type, expected)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_invalid_type_codes_and_empty_sequences_surface_type_errors(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            promote = self._promote_function(runtime)
            result_type = self._result_type_function(runtime)
            for left_type, right_type in ((-1, 1), (0, 1), (1, 25)):
                with self.subTest(
                    api="promote", left=left_type, right=right_type
                ):
                    runtime.dll.cnp_clear_error()
                    self.assertEqual(0, promote(left_type, right_type))
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual(
                        "cnp_promote_types_public", error.function
                    )
                    self.assertIn("valid CNP_TYPE", error.message)

            for count in (-1, 0):
                with self.subTest(api="result_type", count=count):
                    runtime.dll.cnp_clear_error()
                    self.assertEqual(0, result_type(count, None))
                    error = runtime.error_state()
                    self.assertEqual(-1, error.status)
                    self.assertEqual("cnp_result_type", error.function)
                    self.assertIn("at least one array", error.message)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_null_result_type_inputs_fail_explicitly_instead_of_crashing(
        self,
    ) -> None:
        code = f"""
import ctypes

dll = ctypes.CDLL({str(DLL)!r})
dll.cnp_init.argtypes = []
dll.cnp_init.restype = ctypes.c_int
dll.cnp_cleanup.argtypes = []
dll.cnp_cleanup.restype = None
dll.cnp_clear_error.argtypes = []
dll.cnp_clear_error.restype = None
dll.cnp_get_error.argtypes = [ctypes.c_void_p]
dll.cnp_get_error.restype = ctypes.c_int
function = dll.cnp_result_type
function.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_void_p)]
function.restype = ctypes.c_int

if dll.cnp_init() != 0:
    raise SystemExit(10)
for arrays in (None, (ctypes.c_void_p * 1)()):
    dll.cnp_clear_error()
    if function(1, arrays) != 0:
        raise SystemExit(11)
    if dll.cnp_get_error(None) != -1:
        raise SystemExit(12)
dll.cnp_cleanup()
"""
        completed = subprocess.run(
            [sys.executable, "-B", "-c", code],
            capture_output=True,
            text=True,
            check=False,
        )
        self.assertEqual(
            0,
            completed.returncode,
            msg=(completed.stdout + completed.stderr),
        )


class CastingSemanticsTests(unittest.TestCase):
    _REPRESENTED_TYPES = DtypeMetadataSemanticsTests._REPRESENTED_TYPES
    _CASTING_MODES = (
        (0, "no"),
        (1, "equiv"),
        (2, "safe"),
        (3, "same_kind"),
        (4, "unsafe"),
    )

    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_dtype_can_cast
        function.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
        function.restype = ctypes.c_bool
        return function

    def test_pairwise_casting_modes_match_numpy_125_for_all_represented_types(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for source_type, source_dtype in self._REPRESENTED_TYPES:
                for destination_type, destination_dtype in self._REPRESENTED_TYPES:
                    for casting_mode, casting_name in self._CASTING_MODES:
                        with self.subTest(
                            source_type=source_type,
                            destination_type=destination_type,
                            casting=casting_name,
                        ):
                            expected = np.can_cast(
                                source_dtype,
                                destination_dtype,
                                casting=casting_name,
                            )
                            runtime.dll.cnp_clear_error()
                            actual = function(
                                source_type,
                                destination_type,
                                casting_mode,
                            )
                            self.assertEqual(expected, actual)
                            self.assertEqual(0, runtime.error_state().status)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_invalid_dtype_and_casting_codes_surface_native_type_errors(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for source_type, destination_type, casting_mode in (
                (-1, 1, 2),
                (0, 1, 2),
                (1, 25, 2),
                (1, 1, -1),
                (1, 1, 5),
            ):
                with self.subTest(
                    source_type=source_type,
                    destination_type=destination_type,
                    casting_mode=casting_mode,
                ):
                    runtime.dll.cnp_clear_error()
                    self.assertFalse(
                        function(
                            source_type,
                            destination_type,
                            casting_mode,
                        )
                    )
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual("cnp_dtype_can_cast", error.function)
                    self.assertIn("valid", error.message)
            self.assertEqual(baseline, runtime.retained_bytes)


class CopytoSemanticsTests(unittest.TestCase):
    _NUMERIC_DTYPES = (
        np.dtype(np.bool_),
        np.dtype(np.int8),
        np.dtype(np.uint8),
        np.dtype(np.int16),
        np.dtype(np.uint16),
        np.dtype(np.int32),
        np.dtype(np.uint32),
        np.dtype(np.int64),
        np.dtype(np.uint64),
        np.dtype(np.float16),
        np.dtype(np.float32),
        np.dtype(np.float64),
        np.dtype(np.complex64),
        np.dtype(np.complex128),
    )

    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_copyto
        function.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int]
        function.restype = ctypes.c_int
        return function

    @staticmethod
    def _representative_values(dtype: np.dtype) -> np.ndarray:
        if dtype.kind == "b":
            values = [False, True, True]
        elif dtype.kind == "i":
            values = [-3, 0, 7]
        elif dtype.kind == "u":
            values = [0, 3, 7]
        elif dtype.kind == "f":
            values = [0.0, 1.5, 7.25]
        else:
            values = [1.25j, 1.5 - 2.0j, 7.25 + 0.0j]
        return np.asarray(values, dtype=dtype)

    def test_all_numeric_unsafe_casts_match_numpy_125_bytes(self) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for source_dtype in self._NUMERIC_DTYPES:
                source_values = self._representative_values(source_dtype)
                for destination_dtype in self._NUMERIC_DTYPES:
                    with self.subTest(
                        source=str(source_dtype),
                        destination=str(destination_dtype),
                    ):
                        expected = np.zeros(
                            source_values.shape, dtype=destination_dtype
                        )
                        with warnings.catch_warnings():
                            warnings.simplefilter("ignore", np.ComplexWarning)
                            np.copyto(
                                expected,
                                source_values,
                                casting="unsafe",
                            )
                        with runtime.from_numpy(
                            source_values
                        ) as source, runtime.from_numpy(
                            np.zeros_like(expected)
                        ) as destination:
                            runtime.dll.cnp_clear_error()
                            self.assertEqual(
                                0,
                                function(
                                    destination.pointer,
                                    source.pointer,
                                    4,
                                ),
                                runtime.error_state(),
                            )
                            actual = destination.to_numpy()
                            self.assertEqual(
                                expected.tobytes(), actual.tobytes()
                            )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_broadcast_strides_empty_dimensions_and_overlap_match_numpy_125(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)

            initial_destination = np.full((3, 2), -1, dtype=np.int64)
            source_values = np.asarray(
                [2**53 + 1, -(2**53) - 3, 2**62 + 5],
                dtype=np.int64,
            )
            expected_base = initial_destination.copy()
            np.copyto(expected_base.T, source_values)
            with runtime.from_numpy(
                initial_destination
            ) as destination_base, runtime.transpose(
                destination_base
            ) as destination, runtime.from_numpy(source_values) as source:
                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    0,
                    function(destination.pointer, source.pointer, 3),
                    runtime.error_state(),
                )
                np.testing.assert_array_equal(
                    expected_base, destination_base.to_numpy(), strict=True
                )

            source_base_values = np.asarray(
                [
                    [2**53 + 1, -(2**53) - 1],
                    [2**60 + 3, -(2**60) - 3],
                    [2**62 + 5, -(2**62) - 5],
                ],
                dtype=np.int64,
            )
            expected = source_base_values.T.copy()
            with runtime.from_numpy(
                source_base_values
            ) as source_base, runtime.transpose(
                source_base
            ) as source, runtime.from_numpy(
                np.zeros(expected.shape, dtype=np.int64)
            ) as destination:
                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    0,
                    function(destination.pointer, source.pointer, 3),
                    runtime.error_state(),
                )
                np.testing.assert_array_equal(
                    expected, destination.to_numpy(), strict=True
                )

            empty_source = np.empty((1, 3), dtype=np.float32)
            empty_destination = np.empty((2, 0, 3), dtype=np.float32)
            with runtime.from_numpy(
                empty_source
            ) as source, runtime.from_numpy(
                empty_destination
            ) as destination:
                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    0,
                    function(destination.pointer, source.pointer, 3),
                    runtime.error_state(),
                )
                self.assertEqual((2, 0, 3), destination.shape)

            overlap_values = np.asarray(
                [[1, 2], [3, 4]], dtype=np.int64
            )
            expected_overlap = overlap_values.copy()
            np.copyto(expected_overlap, expected_overlap.T)
            with runtime.from_numpy(overlap_values) as destination, runtime.transpose(
                destination
            ) as source:
                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    0,
                    function(destination.pointer, source.pointer, 3),
                    runtime.error_state(),
                )
                np.testing.assert_array_equal(
                    expected_overlap, destination.to_numpy(), strict=True
                )

            self.assertEqual(baseline, runtime.retained_bytes)

    def test_failures_are_explicit_and_leave_destination_unchanged(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            original = np.asarray(
                [[11, 12, 13], [21, 22, 23]], dtype=np.int16
            )

            with runtime.from_numpy(original) as destination, runtime.from_numpy(
                np.asarray([[1.5, 2.5, 3.5], [4.5, 5.5, 6.5]])
            ) as source:
                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    -3,
                    function(destination.pointer, source.pointer, 2),
                )
                error = runtime.error_state()
                self.assertEqual("cnp_copyto", error.function)
                self.assertIn("cast", error.message.lower())
                np.testing.assert_array_equal(
                    original, destination.to_numpy(), strict=True
                )

                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    -3,
                    function(destination.pointer, source.pointer, 5),
                )
                error = runtime.error_state()
                self.assertEqual("cnp_copyto", error.function)
                self.assertIn("casting", error.message.lower())
                np.testing.assert_array_equal(
                    original, destination.to_numpy(), strict=True
                )

            with runtime.from_numpy(original) as destination, runtime.from_numpy(
                np.arange(6, dtype=np.int16).reshape(3, 2)
            ) as source:
                runtime.dll.cnp_clear_error()
                self.assertEqual(
                    -7,
                    function(destination.pointer, source.pointer, 3),
                )
                error = runtime.error_state()
                self.assertEqual("cnp_copyto", error.function)
                self.assertIn("broadcast", error.message.lower())
                np.testing.assert_array_equal(
                    original, destination.to_numpy(), strict=True
                )

            with runtime.from_numpy(
                np.asarray([1], dtype=np.int8)
            ) as probe:
                for destination_pointer, source_pointer in (
                    (None, probe.pointer),
                    (probe.pointer, None),
                    (None, None),
                ):
                    with self.subTest(
                        destination=destination_pointer,
                        source=source_pointer,
                    ):
                        runtime.dll.cnp_clear_error()
                        self.assertEqual(
                            -1,
                            function(
                                destination_pointer,
                                source_pointer,
                                3,
                            ),
                        )
                        error = runtime.error_state()
                        self.assertEqual("cnp_copyto", error.function)
                        self.assertIn("required", error.message.lower())

            self.assertEqual(baseline, runtime.retained_bytes)


class ClipArraySemanticsTests(unittest.TestCase):
    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_clip_array
        function.argtypes = [
            ctypes.c_void_p,
            ctypes.c_void_p,
            ctypes.c_void_p,
        ]
        function.restype = ctypes.c_void_p
        return function

    def test_array_bounds_broadcast_and_preserve_numpy_dtype(self) -> None:
        source_values = np.asarray(
            [[-9, 1, 12], [3, 15, 7]], dtype=np.int16
        )
        minimum_values = np.asarray([0, 2, 4], dtype=np.int64)
        maximum_values = np.asarray([[5], [8]], dtype=np.int64)
        expected = np.clip(
            source_values, minimum_values, maximum_values
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            with runtime.from_numpy(source_values) as source, runtime.from_numpy(
                minimum_values
            ) as minimum, runtime.from_numpy(maximum_values) as maximum:
                runtime.dll.cnp_clear_error()
                pointer = function(
                    source.pointer, minimum.pointer, maximum.pointer
                )
                with runtime._owned_result(pointer, "cnp_clip_array") as actual:
                    np.testing.assert_array_equal(
                        expected, actual.to_numpy(), strict=True
                    )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_scalar_promotion_empty_dimensions_and_uint64_precision(self) -> None:
        cases = (
            (
                "int8_scalar_bounds",
                np.asarray([-3, 2, 9], dtype=np.int8),
                np.asarray(0, dtype=np.int16),
                np.asarray(5, dtype=np.int16),
            ),
            (
                "float32_scalar_bounds",
                np.asarray([-1.0, 0.25, 2.0], dtype=np.float32),
                np.asarray(0.1, dtype=np.float64),
                np.asarray(0.75, dtype=np.float64),
            ),
            (
                "bool_array_bounds",
                np.asarray([False, True, True], dtype=np.bool_),
                np.asarray([0, 0, 1], dtype=np.int64),
                np.asarray([1, 2, 2], dtype=np.int64),
            ),
            (
                "uint64_exact",
                np.asarray(
                    [2**53 + 1, 2**63 + 5, 2**64 - 1],
                    dtype=np.uint64,
                ),
                np.asarray(2**53 + 2, dtype=np.uint64),
                np.asarray(2**64 - 2, dtype=np.uint64),
            ),
            (
                "empty",
                np.empty((2, 0, 3), dtype=np.float16),
                np.zeros((1, 3), dtype=np.float32),
                None,
            ),
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for case, source_values, minimum_values, maximum_values in cases:
                with self.subTest(case=case), contextlib.ExitStack() as stack:
                    source = stack.enter_context(
                        runtime.from_numpy(source_values)
                    )
                    minimum = (
                        stack.enter_context(
                            runtime.from_numpy(minimum_values)
                        )
                        if minimum_values is not None
                        else None
                    )
                    maximum = (
                        stack.enter_context(
                            runtime.from_numpy(maximum_values)
                        )
                        if maximum_values is not None
                        else None
                    )
                    expected = np.clip(
                        source_values, minimum_values, maximum_values
                    )
                    runtime.dll.cnp_clear_error()
                    pointer = function(
                        source.pointer,
                        minimum.pointer if minimum else None,
                        maximum.pointer if maximum else None,
                    )
                    with runtime._owned_result(
                        pointer, "cnp_clip_array"
                    ) as actual:
                        np.testing.assert_array_equal(
                            expected, actual.to_numpy(), strict=True
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_missing_and_incompatible_operands_fail_explicitly(self) -> None:
        source_values = np.arange(6, dtype=np.float64).reshape(2, 3)
        incompatible_values = np.ones((2, 2), dtype=np.float64)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            with runtime.from_numpy(source_values) as source, runtime.from_numpy(
                incompatible_values
            ) as incompatible:
                for case, source_pointer, minimum_pointer, maximum_pointer, status in (
                    ("source", None, incompatible.pointer, None, -1),
                    ("bounds", source.pointer, None, None, -1),
                    (
                        "broadcast",
                        source.pointer,
                        incompatible.pointer,
                        None,
                        -7,
                    ),
                ):
                    with self.subTest(case=case):
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        pointer = function(
                            source_pointer,
                            minimum_pointer,
                            maximum_pointer,
                        )
                        error = runtime.error_state()
                        if pointer:
                            runtime.dll.cnp_array_free(
                                ctypes.c_void_p(pointer)
                            )
                        self.assertFalse(pointer)
                        self.assertEqual(status, error.status)
                        self.assertEqual("cnp_clip_array", error.function)
                        if case == "source":
                            self.assertIn("source", error.message.lower())
                        elif case == "bounds":
                            self.assertIn("min", error.message.lower())
                            self.assertIn("max", error.message.lower())
                        else:
                            self.assertIn("broadcast", error.message.lower())
                        self.assertEqual(before_call, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_nan_bounds_one_sided_ranges_and_signed_zero_match_numpy(self) -> None:
        source_values = np.asarray(
            [np.nan, -0.0, 0.0, -np.inf, np.inf, -3.0, 4.0],
            dtype=np.float64,
        )
        cases = (
            ("minimum_nan", np.asarray(np.nan), np.asarray(1.0)),
            ("maximum_nan", np.asarray(0.0), np.asarray(np.nan)),
            ("reversed", np.asarray(2.0), np.asarray(1.0)),
            ("minimum_only", np.asarray(0.0), None),
            ("maximum_only", None, np.asarray(1.0)),
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            with runtime.from_numpy(source_values) as source:
                for case, minimum_values, maximum_values in cases:
                    with self.subTest(case=case), contextlib.ExitStack() as stack:
                        minimum = (
                            stack.enter_context(
                                runtime.from_numpy(minimum_values)
                            )
                            if minimum_values is not None
                            else None
                        )
                        maximum = (
                            stack.enter_context(
                                runtime.from_numpy(maximum_values)
                            )
                            if maximum_values is not None
                            else None
                        )
                        expected = np.clip(
                            source_values, minimum_values, maximum_values
                        )
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        pointer = function(
                            source.pointer,
                            minimum.pointer if minimum else None,
                            maximum.pointer if maximum else None,
                        )
                        with runtime._owned_result(
                            pointer, "cnp_clip_array"
                        ) as result:
                            actual = result.to_numpy()
                            np.testing.assert_array_equal(
                                expected, actual, strict=True
                            )
                            np.testing.assert_array_equal(
                                np.signbit(expected), np.signbit(actual)
                            )
                        self.assertEqual(before_call, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_fortran_source_preserves_numpy_iteration_order(self) -> None:
        stored_values = np.asarray(
            [[-3.0, 8.0], [2.0, 7.0], [5.0, -1.0]],
            dtype=np.float32,
        )
        source_values = stored_values.T
        minimum_values = np.asarray(0.0, dtype=np.float64)
        maximum_values = np.asarray(6.0, dtype=np.float64)
        expected = np.clip(
            source_values, minimum_values, maximum_values
        )
        self.assertTrue(expected.flags.f_contiguous)
        self.assertFalse(expected.flags.c_contiguous)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            with runtime.from_numpy(stored_values) as stored, runtime.transpose(
                stored
            ) as source, runtime.from_numpy(
                minimum_values
            ) as minimum, runtime.from_numpy(maximum_values) as maximum:
                self.assertFalse(source.c_contiguous)
                self.assertTrue(source.f_contiguous)
                runtime.dll.cnp_clear_error()
                pointer = function(
                    source.pointer, minimum.pointer, maximum.pointer
                )
                with runtime._owned_result(
                    pointer, "cnp_clip_array"
                ) as actual:
                    np.testing.assert_array_equal(
                        expected, actual.to_numpy(), strict=True
                    )
                    self.assertFalse(actual.c_contiguous)
                    self.assertTrue(actual.f_contiguous)
                    self.assertEqual(expected.strides, actual.strides)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_complex_lexicographic_order_matches_numpy(self) -> None:
        source_template = np.asarray(
            [1.0 + 2.0j, 1.0 + 0.0j, 0.0 + 5.0j,
             2.0 - 4.0j, -1.0 + 3.0j]
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for dtype in (np.dtype(np.complex64), np.dtype(np.complex128)):
                with self.subTest(dtype=str(dtype)):
                    source_values = source_template.astype(dtype)
                    minimum_values = np.asarray(1.0 + 1.0j, dtype=dtype)
                    maximum_values = np.asarray(2.0 + 0.0j, dtype=dtype)
                    expected = np.clip(
                        source_values, minimum_values, maximum_values
                    )
                    with runtime.from_numpy(
                        source_values
                    ) as source, runtime.from_numpy(
                        minimum_values
                    ) as minimum, runtime.from_numpy(maximum_values) as maximum:
                        runtime.dll.cnp_clear_error()
                        pointer = function(
                            source.pointer, minimum.pointer, maximum.pointer
                        )
                        with runtime._owned_result(
                            pointer, "cnp_clip_array"
                        ) as actual:
                            np.testing.assert_array_equal(
                                expected, actual.to_numpy(), strict=True
                            )
            self.assertEqual(baseline, runtime.retained_bytes)


class AroundSemanticsTests(unittest.TestCase):
    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_around
        function.argtypes = [ctypes.c_void_p, ctypes.c_int]
        function.restype = ctypes.c_void_p
        return function

    @staticmethod
    def _expected(values: np.ndarray, decimals: int) -> np.ndarray:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", RuntimeWarning)
            return np.around(values, decimals)

    @staticmethod
    def _assert_matches_numpy(
        expected: np.ndarray, actual: np.ndarray
    ) -> None:
        np.testing.assert_array_equal(expected, actual, strict=True)
        if expected.dtype.kind == "f":
            np.testing.assert_array_equal(
                np.signbit(expected), np.signbit(actual)
            )
        elif expected.dtype.kind == "c":
            np.testing.assert_array_equal(
                np.signbit(expected.real), np.signbit(actual.real)
            )
            np.testing.assert_array_equal(
                np.signbit(expected.imag), np.signbit(actual.imag)
            )

    def test_numeric_dtype_loops_and_ties_match_numpy_125(self) -> None:
        cases: list[tuple[str, np.ndarray, int]] = [
            (
                "bool_zero_decimals",
                np.asarray([False, True], dtype=np.bool_),
                0,
            )
        ]
        signed_values = [-125, -115, -105, -25, -15, -5,
                         0, 5, 15, 25, 105, 115, 125]
        unsigned_values = [0, 5, 15, 25, 105, 115, 125]
        for dtype in (
            np.int8, np.uint8, np.int16, np.uint16,
            np.int32, np.uint32, np.int64, np.uint64,
        ):
            values = signed_values if np.issubdtype(
                dtype, np.signedinteger
            ) else unsigned_values
            array = np.asarray(values, dtype=dtype)
            cases.extend((
                (f"{np.dtype(dtype).name}_negative", array, -1),
                (f"{np.dtype(dtype).name}_positive", array, 3),
            ))
        real_values = np.asarray(
            [-2.675, -2.5, -1.25, -0.5, -0.0,
             0.0, 0.5, 1.25, 2.5, 2.675]
        )
        for dtype in (np.float16, np.float32, np.float64):
            array = real_values.astype(dtype)
            for decimals in (-2, 0, 1, 5):
                cases.append((
                    f"{np.dtype(dtype).name}_{decimals}",
                    array,
                    decimals,
                ))
        complex_values = np.asarray(
            [-2.675 + 1.25j, -0.0 - 0.0j, 0.5 + 2.5j,
             1.25 - 2.675j, 2.5 - 0.5j]
        )
        for dtype in (np.complex64, np.complex128):
            array = complex_values.astype(dtype)
            for decimals in (-2, 0, 1, 5):
                cases.append((
                    f"{np.dtype(dtype).name}_{decimals}",
                    array,
                    decimals,
                ))

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for case, values, decimals in cases:
                with self.subTest(case=case), runtime.from_numpy(values) as source:
                    expected = self._expected(values, decimals)
                    before_call = runtime.retained_bytes
                    runtime.dll.cnp_clear_error()
                    pointer = function(source.pointer, decimals)
                    with runtime._owned_result(
                        pointer, "cnp_around"
                    ) as result:
                        self._assert_matches_numpy(
                            expected, result.to_numpy()
                        )
                    self.assertEqual(before_call, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_large_integer_conversion_edges_match_numpy_125(self) -> None:
        cases = (
            np.asarray(
                [-(2**63), -(2**53 + 1), 2**53 + 1, 2**63 - 1],
                dtype=np.int64,
            ),
            np.asarray(
                [2**53 + 1, 2**63 - 1, 2**63 + 1, 2**64 - 1],
                dtype=np.uint64,
            ),
        )
        decimals_cases = (-1, -2, -15, -19)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for values in cases:
                for decimals in decimals_cases:
                    with self.subTest(
                        dtype=str(values.dtype), decimals=decimals
                    ), runtime.from_numpy(values) as source:
                        expected = self._expected(values, decimals)
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        pointer = function(source.pointer, decimals)
                        with runtime._owned_result(
                            pointer, "cnp_around"
                        ) as result:
                            self._assert_matches_numpy(
                                expected, result.to_numpy()
                            )
                        self.assertEqual(
                            before_call, runtime.retained_bytes
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_nonfinite_extreme_decimals_and_signed_zero_match_numpy_125(
        self,
    ) -> None:
        real_values = np.asarray(
            [np.nan, np.inf, -np.inf, -0.0, 0.0, -1.25, 1.25],
            dtype=np.float64,
        )
        complex_values = np.asarray(
            [np.nan + 1.25j, np.inf - 0.0j,
             -0.0 + np.nan * 1j, -1.25 - 2.5j],
            dtype=np.complex128,
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for values in (real_values, complex_values):
                for decimals in (-309, -2, 0, 2, 309):
                    with self.subTest(
                        dtype=str(values.dtype), decimals=decimals
                    ), runtime.from_numpy(values) as source:
                        expected = self._expected(values, decimals)
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        pointer = function(source.pointer, decimals)
                        with runtime._owned_result(
                            pointer, "cnp_around"
                        ) as result:
                            self._assert_matches_numpy(
                                expected, result.to_numpy()
                            )
                        self.assertEqual(
                            before_call, runtime.retained_bytes
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_scalar_empty_and_fortran_inputs_preserve_numpy_layout(
        self,
    ) -> None:
        scalar_values = np.asarray(1.25, dtype=np.float32)
        empty_values = np.empty((2, 0, 3), dtype=np.float16)
        stored_values = np.asarray(
            [[-2.675, 1.25], [2.5, -0.0], [0.5, -1.25]],
            dtype=np.float32,
        )
        expected_fortran = np.around(stored_values.T, 1)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for values, decimals in (
                (scalar_values, 1),
                (empty_values, -2),
            ):
                with self.subTest(shape=values.shape), runtime.from_numpy(
                    values
                ) as source:
                    pointer = function(source.pointer, decimals)
                    with runtime._owned_result(
                        pointer, "cnp_around"
                    ) as result:
                        self._assert_matches_numpy(
                            np.around(values, decimals), result.to_numpy()
                        )

            with runtime.from_numpy(stored_values) as stored, runtime.transpose(
                stored
            ) as source:
                pointer = function(source.pointer, 1)
                with runtime._owned_result(pointer, "cnp_around") as result:
                    self._assert_matches_numpy(
                        expected_fortran, result.to_numpy()
                    )
                    self.assertFalse(result.c_contiguous)
                    self.assertTrue(result.f_contiguous)
                    self.assertEqual(expected_fortran.strides, result.strides)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_invalid_operands_are_explicit_and_leak_free(self) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)

            runtime.dll.cnp_clear_error()
            self.assertFalse(function(None, 0))
            error = runtime.error_state()
            self.assertNotEqual(0, error.status)
            self.assertEqual("cnp_around", error.function)
            self.assertIn("source", error.message.lower())
            self.assertEqual(baseline, runtime.retained_bytes)

            with runtime.from_numpy(
                np.asarray([False, True], dtype=np.bool_)
            ) as boolean_source:
                for decimals in (-1, 1):
                    with self.subTest(decimals=decimals):
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        self.assertFalse(
                            function(boolean_source.pointer, decimals)
                        )
                        error = runtime.error_state()
                        self.assertEqual(-3, error.status)
                        self.assertEqual("cnp_around", error.function)
                        self.assertIn("bool", error.message.lower())
                        self.assertEqual(
                            before_call, runtime.retained_bytes
                        )

            datetime_data = ctypes.c_int64(1)
            datetime_shape = (ctypes.c_int64 * 1)(1)
            runtime.dll.cnp_clear_error()
            datetime_pointer = runtime.dll.cnp_array_from_data(
                ctypes.byref(datetime_data),
                1,
                datetime_shape,
                22,
                0,
            )
            with runtime._owned_result(
                datetime_pointer, "cnp_array_from_data"
            ) as datetime_source:
                before_call = runtime.retained_bytes
                runtime.dll.cnp_clear_error()
                self.assertFalse(function(datetime_source.pointer, 0))
                error = runtime.error_state()
                self.assertEqual(-3, error.status)
                self.assertEqual("cnp_around", error.function)
                self.assertIn("dtype", error.message.lower())
                self.assertEqual(before_call, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)


class RoundAliasSemanticsTests(unittest.TestCase):
    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_round
        function.argtypes = [ctypes.c_void_p, ctypes.c_int]
        function.restype = ctypes.c_void_p
        return function

    def test_alias_values_dtypes_and_layout_match_numpy_125(self) -> None:
        cases = (
            (np.asarray([False, True], dtype=np.bool_), 0),
            (np.asarray([-125, -115, 15, 25], dtype=np.int8), -1),
            (
                np.asarray(
                    [2**53 + 1, 2**63 + 1, 2**64 - 1],
                    dtype=np.uint64,
                ),
                -15,
            ),
            (
                np.asarray([-2.675, -0.0, 1.25, 2.5], dtype=np.float16),
                5,
            ),
            (
                np.asarray(
                    [np.nan, np.inf, -0.0, -2.5, 2.5],
                    dtype=np.float64,
                ),
                0,
            ),
            (
                np.asarray(
                    [-2.675 + 1.25j, -0.0 - 0.0j, 2.5 - 0.5j],
                    dtype=np.complex64,
                ),
                1,
            ),
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for values, decimals in cases:
                with self.subTest(
                    dtype=str(values.dtype), decimals=decimals
                ), runtime.from_numpy(values) as source:
                    expected = AroundSemanticsTests._expected(
                        values, decimals
                    )
                    before_call = runtime.retained_bytes
                    runtime.dll.cnp_clear_error()
                    pointer = function(source.pointer, decimals)
                    with runtime._owned_result(
                        pointer, "cnp_round"
                    ) as result:
                        AroundSemanticsTests._assert_matches_numpy(
                            expected, result.to_numpy()
                        )
                    self.assertEqual(before_call, runtime.retained_bytes)

            stored_values = np.asarray(
                [[-2.675, 1.25], [2.5, -0.0], [0.5, -1.25]],
                dtype=np.float32,
            )
            with runtime.from_numpy(stored_values) as stored, runtime.transpose(
                stored
            ) as source:
                expected = np.round(stored_values.T, 1)
                pointer = function(source.pointer, 1)
                with runtime._owned_result(pointer, "cnp_round") as result:
                    AroundSemanticsTests._assert_matches_numpy(
                        expected, result.to_numpy()
                    )
                    self.assertFalse(result.c_contiguous)
                    self.assertTrue(result.f_contiguous)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_alias_errors_are_relabelled_and_leak_free(self) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)

            runtime.dll.cnp_clear_error()
            self.assertFalse(function(None, 0))
            error = runtime.error_state()
            self.assertNotEqual(0, error.status)
            self.assertEqual("cnp_round", error.function)
            self.assertIn("source", error.message.lower())

            with runtime.from_numpy(
                np.asarray([False, True], dtype=np.bool_)
            ) as source:
                before_call = runtime.retained_bytes
                runtime.dll.cnp_clear_error()
                self.assertFalse(function(source.pointer, 1))
                error = runtime.error_state()
                self.assertEqual(-3, error.status)
                self.assertEqual("cnp_round", error.function)
                self.assertIn("bool", error.message.lower())
                self.assertEqual(before_call, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)


class UnaryRoundingSemanticsTests(unittest.TestCase):
    _OPERATIONS = (
        ("cnp_rint", np.rint),
        ("cnp_fix", np.fix),
        ("cnp_trunc", np.trunc),
        ("cnp_floor", np.floor),
        ("cnp_ceil", np.ceil),
    )

    @staticmethod
    def _function(runtime: CnumpyRuntime, symbol: str):
        function = getattr(runtime.dll, symbol)
        function.argtypes = [ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    def test_numeric_dtype_dispatch_and_values_match_numpy_125(self) -> None:
        arrays = [np.asarray([False, True], dtype=np.bool_)]
        for dtype in (
            np.int8, np.uint8, np.int16, np.uint16,
            np.int32, np.uint32, np.int64, np.uint64,
        ):
            info = np.iinfo(dtype)
            values = (
                [info.min, -2, -1, 0, 1, 2, info.max]
                if np.issubdtype(dtype, np.signedinteger)
                else [0, 1, 2, info.max]
            )
            arrays.append(np.asarray(values, dtype=dtype))
        real_values = np.asarray(
            [-2.5, -1.5, -0.5, -0.0, 0.0,
             0.5, 1.5, 2.5, np.nan, np.inf]
        )
        arrays.extend(
            real_values.astype(dtype)
            for dtype in (np.float16, np.float32, np.float64)
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for symbol, oracle in self._OPERATIONS:
                function = self._function(runtime, symbol)
                for values in arrays:
                    with self.subTest(
                        symbol=symbol, dtype=str(values.dtype)
                    ), runtime.from_numpy(values) as source:
                        expected = oracle(values)
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        pointer = function(source.pointer)
                        with runtime._owned_result(
                            pointer, symbol
                        ) as result:
                            AroundSemanticsTests._assert_matches_numpy(
                                expected, result.to_numpy()
                            )
                        self.assertEqual(
                            before_call, runtime.retained_bytes
                        )

            complex_values = np.asarray(
                [-2.5 + 1.5j, -0.0 - 0.0j,
                 0.5 + 2.5j, np.nan + 1.0j]
            )
            rint = self._function(runtime, "cnp_rint")
            for dtype in (np.complex64, np.complex128):
                values = complex_values.astype(dtype)
                with self.subTest(
                    symbol="cnp_rint", dtype=str(values.dtype)
                ), runtime.from_numpy(values) as source:
                    pointer = rint(source.pointer)
                    with runtime._owned_result(pointer, "cnp_rint") as result:
                        AroundSemanticsTests._assert_matches_numpy(
                            np.rint(values), result.to_numpy()
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_scalar_empty_and_fortran_layouts_match_numpy_125(self) -> None:
        stored_values = np.asarray(
            [[-2.5, 1.5], [2.25, -0.0], [0.5, -1.25]],
            dtype=np.float32,
        )
        scalar_values = np.asarray(-0.5, dtype=np.float16)
        empty_values = np.empty((2, 0, 3), dtype=np.float64)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for symbol, oracle in self._OPERATIONS:
                function = self._function(runtime, symbol)
                for values in (scalar_values, empty_values):
                    with self.subTest(
                        symbol=symbol, shape=values.shape
                    ), runtime.from_numpy(values) as source:
                        pointer = function(source.pointer)
                        with runtime._owned_result(
                            pointer, symbol
                        ) as result:
                            AroundSemanticsTests._assert_matches_numpy(
                                oracle(values), result.to_numpy()
                            )

                with runtime.from_numpy(
                    stored_values
                ) as stored, runtime.transpose(stored) as source:
                    expected = oracle(stored_values.T)
                    pointer = function(source.pointer)
                    with runtime._owned_result(pointer, symbol) as result:
                        AroundSemanticsTests._assert_matches_numpy(
                            expected, result.to_numpy()
                        )
                        self.assertFalse(result.c_contiguous)
                        self.assertTrue(result.f_contiguous)
                        self.assertEqual(expected.strides, result.strides)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_unsupported_complex_inputs_are_explicit_and_leak_free(
        self,
    ) -> None:
        values = np.asarray([1.5 + 2.5j], dtype=np.complex128)
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            with runtime.from_numpy(values) as source:
                for symbol, _ in self._OPERATIONS[1:]:
                    with self.subTest(symbol=symbol):
                        function = self._function(runtime, symbol)
                        before_call = runtime.retained_bytes
                        runtime.dll.cnp_clear_error()
                        self.assertFalse(function(source.pointer))
                        error = runtime.error_state()
                        self.assertEqual(-3, error.status)
                        self.assertEqual(symbol, error.function)
                        self.assertIn("complex", error.message.lower())
                        self.assertEqual(
                            before_call, runtime.retained_bytes
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_null_inputs_fail_explicitly_instead_of_crashing(self) -> None:
        symbols = tuple(symbol for symbol, _ in self._OPERATIONS)
        code = f"""
import ctypes

class ErrorState(ctypes.Structure):
    _fields_ = [
        ('status', ctypes.c_int),
        ('message', ctypes.c_char * 256),
        ('function', ctypes.c_char * 64),
    ]

dll = ctypes.CDLL({str(DLL)!r})
dll.cnp_init.argtypes = []
dll.cnp_init.restype = ctypes.c_int
dll.cnp_cleanup.argtypes = []
dll.cnp_cleanup.restype = None
dll.cnp_clear_error.argtypes = []
dll.cnp_clear_error.restype = None
dll.cnp_get_error.argtypes = [ctypes.POINTER(ErrorState)]
dll.cnp_get_error.restype = ctypes.c_int
if dll.cnp_init() != 0:
    raise SystemExit(10)
for symbol in {symbols!r}:
    function = getattr(dll, symbol)
    function.argtypes = [ctypes.c_void_p]
    function.restype = ctypes.c_void_p
    dll.cnp_clear_error()
    if function(None):
        raise SystemExit(11)
    state = ErrorState()
    if dll.cnp_get_error(ctypes.byref(state)) == 0:
        raise SystemExit(12)
    if state.function.split(b'\\0', 1)[0].decode() != symbol:
        raise SystemExit(13)
dll.cnp_cleanup()
"""
        completed = subprocess.run(
            [sys.executable, "-B", "-c", code],
            capture_output=True,
            text=True,
            check=False,
        )
        self.assertEqual(
            0,
            completed.returncode,
            msg=(completed.stdout + completed.stderr),
        )


class AbsoluteSemanticsTests(unittest.TestCase):
    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_absolute
        function.argtypes = [ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    @staticmethod
    def _assert_matches_numpy(
        source: np.ndarray, actual: np.ndarray
    ) -> None:
        expected = np.absolute(source)
        if not np.issubdtype(source.dtype, np.complexfloating):
            AroundSemanticsTests._assert_matches_numpy(expected, actual)
            return
        expected_dtype = expected.dtype
        if expected_dtype != actual.dtype:
            raise AssertionError(
                f"dtype mismatch: expected {expected_dtype}, actual {actual.dtype}"
            )
        np.testing.assert_allclose(
            expected,
            actual,
            rtol=float(np.finfo(expected_dtype).eps) * 2.0,
            atol=0.0,
            equal_nan=True,
        )
        np.testing.assert_array_equal(
            np.signbit(expected), np.signbit(actual)
        )

    def test_dtype_dispatch_and_values_match_numpy_125(self) -> None:
        arrays = [np.asarray([False, True], dtype=np.bool_)]
        for dtype in (
            np.int8, np.uint8, np.int16, np.uint16,
            np.int32, np.uint32, np.int64, np.uint64,
        ):
            info = np.iinfo(dtype)
            values = (
                [info.min, -2, -1, 0, 1, 2, info.max]
                if np.issubdtype(dtype, np.signedinteger)
                else [0, 1, 2, info.max]
            )
            arrays.append(np.asarray(values, dtype=dtype))
        real_values = np.asarray(
            [-2.5, -0.0, 0.0, 2.5, -np.nan, -np.inf, np.inf]
        )
        arrays.extend(
            real_values.astype(dtype)
            for dtype in (np.float16, np.float32, np.float64)
        )
        arrays.extend((
            np.asarray(
                [-3.0 + 4.0j, -0.0 - 0.0j,
                 np.nan + 1.0j, np.inf + 2.0j,
                 1e38 + 1e38j, 1e-38 + 1e-38j],
                dtype=np.complex64,
            ),
            np.asarray(
                [-3.0 + 4.0j, -0.0 - 0.0j,
                 np.nan + 1.0j, np.inf + 2.0j,
                 1e308 + 1e308j, 1e-308 + 1e-308j],
                dtype=np.complex128,
            ),
        ))

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for values in arrays:
                with self.subTest(dtype=str(values.dtype)), runtime.from_numpy(
                    values
                ) as source:
                    pointer = function(source.pointer)
                    with runtime._owned_result(
                        pointer, "cnp_absolute"
                    ) as result:
                        self._assert_matches_numpy(values, result.to_numpy())
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_scalar_empty_and_fortran_layouts_match_numpy_125(self) -> None:
        scalar_values = np.asarray(-0.0, dtype=np.float16)
        empty_values = np.empty((2, 0, 3), dtype=np.complex128)
        stored_values = np.asarray(
            [[-3.0 + 4.0j, 1.0 - 1.0j],
             [0.0 - 0.0j, np.inf + 2.0j],
             [5.0 + 12.0j, np.nan + 1.0j]],
            dtype=np.complex64,
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for values in (scalar_values, empty_values):
                with self.subTest(shape=values.shape), runtime.from_numpy(
                    values
                ) as source:
                    pointer = function(source.pointer)
                    with runtime._owned_result(
                        pointer, "cnp_absolute"
                    ) as result:
                        self._assert_matches_numpy(values, result.to_numpy())

            with runtime.from_numpy(
                stored_values
            ) as stored, runtime.transpose(stored) as source:
                expected = np.absolute(stored_values.T)
                pointer = function(source.pointer)
                with runtime._owned_result(pointer, "cnp_absolute") as result:
                    self._assert_matches_numpy(
                        stored_values.T, result.to_numpy()
                    )
                    self.assertFalse(result.c_contiguous)
                    self.assertTrue(result.f_contiguous)
                    self.assertEqual(expected.strides, result.strides)
            self.assertEqual(baseline, runtime.retained_bytes)


