    def test_invalid_inputs_surface_exact_errors_without_retained_memory(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)

            with runtime.from_numpy(np.ones(2, dtype=np.float64)) as valid:
                for left_pointer, right_pointer in (
                    (None, valid.pointer),
                    (valid.pointer, None),
                ):
                    before = runtime.retained_bytes
                    runtime.dll.cnp_clear_error()
                    pointer = function(left_pointer, right_pointer)
                    if pointer:
                        runtime.dll.cnp_array_decref(pointer)
                    self.assertFalse(pointer)
                    error = runtime.error_state()
                    self.assertEqual(-1, error.status)
                    self.assertEqual("cnp_add", error.function)
                    self.assertIn(
                        "left and right arrays are required", error.message
                    )
                    self.assertEqual(before, runtime.retained_bytes)

            with runtime.from_numpy(
                np.ones((2, 3), dtype=np.float32)
            ) as left, runtime.from_numpy(
                np.ones((4,), dtype=np.float32)
            ) as right:
                before = runtime.retained_bytes
                runtime.dll.cnp_clear_error()
                pointer = function(left.pointer, right.pointer)
                if pointer:
                    runtime.dll.cnp_array_decref(pointer)
                self.assertFalse(pointer)
                error = runtime.error_state()
                self.assertEqual(-7, error.status)
                self.assertEqual("cnp_add", error.function)
                self.assertIn("cannot be broadcast together", error.message)
                self.assertEqual(before, runtime.retained_bytes)

            array_new = runtime.dll.cnp_array_new
            array_new.argtypes = [
                ctypes.c_int,
                ctypes.POINTER(ctypes.c_int64),
                ctypes.c_int,
                ctypes.c_int,
            ]
            array_new.restype = ctypes.c_void_p
            shape = (ctypes.c_int64 * 1)(2)
            with runtime._owned_result(
                array_new(1, shape, 19, 0), "cnp_array_new"
            ) as unsupported, runtime.from_numpy(
                np.ones(2, dtype=np.float64)
            ) as numeric:
                before = runtime.retained_bytes
                runtime.dll.cnp_clear_error()
                pointer = function(unsupported.pointer, numeric.pointer)
                if pointer:
                    runtime.dll.cnp_array_decref(pointer)
                self.assertFalse(pointer)
                error = runtime.error_state()
                self.assertEqual(-3, error.status)
                self.assertEqual("cnp_add", error.function)
                self.assertIn(
                    "dtypes bytes and float64 do not support addition",
                    error.message,
                )
                self.assertEqual(before, runtime.retained_bytes)

            self.assertEqual(baseline, runtime.retained_bytes)

    def test_native_strided_views_match_numpy_125(self) -> None:
        class CnpSlice(ctypes.Structure):
            _fields_ = [
                ("start", ctypes.c_int64),
                ("stop", ctypes.c_int64),
                ("step", ctypes.c_int64),
                ("has_start", ctypes.c_bool),
                ("has_stop", ctypes.c_bool),
                ("has_step", ctypes.c_bool),
            ]

        left_base_values = np.arange(24, dtype=np.int16).reshape(4, 6)
        right_base_values = np.linspace(
            -3.0, 8.5, 24, dtype=np.float32
        ).reshape(4, 6)
        expected = np.add(
            left_base_values[::2, ::-2],
            right_base_values[1::2, ::2],
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            slice_function = runtime.dll.cnp_array_slice
            slice_function.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.POINTER(CnpSlice),
            ]
            slice_function.restype = ctypes.c_void_p

            left_base = runtime.from_numpy(left_base_values)
            left_slices = (CnpSlice * 2)(
                CnpSlice(0, 0, 2, False, False, True),
                CnpSlice(0, 0, -2, False, False, True),
            )
            left = runtime._owned_result(
                slice_function(left_base.pointer, 2, left_slices),
                "cnp_array_slice",
            )
            left_base.close()

            right_base = runtime.from_numpy(right_base_values)
            right_slices = (CnpSlice * 2)(
                CnpSlice(1, 0, 2, True, False, True),
                CnpSlice(0, 0, 2, False, False, True),
            )
            right = runtime._owned_result(
                slice_function(right_base.pointer, 2, right_slices),
                "cnp_array_slice",
            )
            right_base.close()

            function = self._function(runtime)
            with left, right:
                pointer = function(left.pointer, right.pointer)
                with runtime._owned_result(pointer, "cnp_add") as result:
                    AroundSemanticsTests._assert_matches_numpy(
                        expected, result.to_numpy()
                    )
            self.assertEqual(baseline, runtime.retained_bytes)

