class FloorDivideSemanticsTests(unittest.TestCase):
    _REAL_DTYPES = SubtractMultiplySemanticsTests._DTYPES[:-2]

    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_floor_divide
        function.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    @staticmethod
    def _values(dtype, right: bool) -> np.ndarray:
        resolved = np.dtype(dtype)
        if np.issubdtype(resolved, np.bool_):
            source = [True, True, True] if right else [False, True, True]
        elif np.issubdtype(resolved, np.unsignedinteger):
            source = [2, 3, 5] if right else [1, 7, 11]
        elif np.issubdtype(resolved, np.integer):
            source = [3, -3, 2] if right else [-7, 7, -1]
        else:
            source = [3.0, -3.0, 2.0] if right else [-7.5, 7.5, -0.0]
        return np.asarray(source, dtype=resolved)

    def test_signed_int64_preserves_integer_precision_and_flooring(self) -> None:
        left_values = np.asarray(
            [
                np.iinfo(np.int64).max,
                np.iinfo(np.int64).min + 1,
                -7,
                7,
                np.iinfo(np.int64).min,
                7,
                -7,
            ],
            dtype=np.int64,
        )
        right_values = np.asarray(
            [3, 3, -3, -3, -1, 0, 0], dtype=np.int64
        )
        with np.errstate(all="ignore"):
            expected = np.floor_divide(left_values, right_values)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            with runtime.from_numpy(left_values) as left, runtime.from_numpy(
                right_values
            ) as right, runtime._owned_result(
                function(left.pointer, right.pointer),
                "cnp_floor_divide",
            ) as actual:
                np.testing.assert_array_equal(expected, actual.to_numpy())
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_pairwise_real_dtype_promotion_matches_numpy_125(self) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for left_dtype in self._REAL_DTYPES:
                left_values = self._values(left_dtype, False)
                for right_dtype in self._REAL_DTYPES:
                    right_values = self._values(right_dtype, True)
