    def test_broadcast_strided_fortran_empty_and_lifetime_semantics(
        self,
    ) -> None:
        class CnpSlice(ctypes.Structure):
            _fields_ = [
                ("start", ctypes.c_int64),
                ("stop", ctypes.c_int64),
                ("step", ctypes.c_int64),
                ("has_start", ctypes.c_bool),
                ("has_stop", ctypes.c_bool),
                ("has_step", ctypes.c_bool),
            ]

        left_base_values = np.arange(
            24, dtype=np.int64
        ).reshape(4, 6) - 11
        left_values = left_base_values[::2, ::-2]
        right_values = np.asarray([3, -3, 2], dtype=np.int32).reshape(1, 3)
        left_fortran = np.asfortranarray(
            np.arange(12, dtype=np.float32).reshape(3, 4) - 5.5
        )
        right_fortran = np.asfortranarray(
            np.linspace(0.5, 6.0, 12, dtype=np.float32).reshape(3, 4)
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            functions = self._functions(runtime)
            slice_function = runtime.dll.cnp_array_slice
            slice_function.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.POINTER(CnpSlice),
            ]
            slice_function.restype = ctypes.c_void_p

            for name, numpy_function in self._OPERATIONS:
                left_base = runtime.from_numpy(left_base_values)
                slices = (CnpSlice * 2)(
                    CnpSlice(0, 0, 2, False, False, True),
                    CnpSlice(0, 0, -2, False, False, True),
                )
                left = runtime._owned_result(
                    slice_function(left_base.pointer, 2, slices),
                    "cnp_array_slice",
                )
                left_base.close()
                right = runtime.from_numpy(right_values)
                actual = runtime._owned_result(
                    functions[name](left.pointer, right.pointer),
                    f"cnp_{name}",
                )
                left.close()
                right.close()
                with self.subTest(
                    operation=name, layout="negative_stride_broadcast"
                ), actual:
                    AroundSemanticsTests._assert_matches_numpy(
                        numpy_function(left_values, right_values),
                        actual.to_numpy(),
                    )

                left_base = runtime.from_numpy(left_fortran.T)
                left = runtime.transpose(left_base, (1, 0))
                left_base.close()
                right_base = runtime.from_numpy(right_fortran.T)
                right = runtime.transpose(right_base, (1, 0))
                right_base.close()
                with self.subTest(
                    operation=name, layout="fortran"
                ), left, right, runtime._owned_result(
                    functions[name](left.pointer, right.pointer),
                    f"cnp_{name}",
                ) as actual:
                    expected = numpy_function(
                        left_fortran, right_fortran
                    )
                    AroundSemanticsTests._assert_matches_numpy(
                        expected, actual.to_numpy()
                    )
                    self.assertEqual(expected.strides, actual.strides)

                empty_left = np.empty((2, 0, 3), dtype=np.int16)
                empty_right = np.empty((1, 1, 3), dtype=np.uint8)
                with self.subTest(
                    operation=name, layout="empty"
                ), runtime.from_numpy(
                    empty_left
                ) as left, runtime.from_numpy(
                    empty_right
                ) as right, runtime._owned_result(
                    functions[name](left.pointer, right.pointer),
                    f"cnp_{name}",
                ) as actual:
                    AroundSemanticsTests._assert_matches_numpy(
                        numpy_function(empty_left, empty_right),
                        actual.to_numpy(),
                    )

            repeat_left = np.arange(1, 33, dtype=np.float64)
            repeat_right = np.linspace(0.5, 3.5, 32, dtype=np.float64)
            with runtime.from_numpy(repeat_left) as left, runtime.from_numpy(
                repeat_right
            ) as right:
                before_calls = runtime.retained_bytes
                for _ in range(128):
                    for name, _ in self._OPERATIONS:
                        with runtime._owned_result(
                            functions[name](left.pointer, right.pointer),
                            f"cnp_{name}",
                        ):
                            pass
                self.assertEqual(before_calls, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)

