            "class ErrorState(ctypes.Structure): pass",
            "ErrorState._fields_ = [('status', ctypes.c_int), ('message', ctypes.c_char * 256), ('function', ctypes.c_char * 64)]",
            "dll.cnp_get_error.argtypes = [ctypes.POINTER(ErrorState)]",
            "dll.cnp_get_error.restype = ctypes.c_int",
            "assert dll.cnp_init() == 0",
            f"for symbol in {symbols!r}:",
