class ConjugateSemanticsTests(unittest.TestCase):
    _SYMBOLS = ("cnp_conj", "cnp_conjugate")

    @staticmethod
    def _function(runtime: CnumpyRuntime, symbol: str):
        function = getattr(runtime.dll, symbol)
        function.argtypes = [ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    @classmethod
    def _call(cls, runtime: CnumpyRuntime, symbol: str, source):
        runtime.dll.cnp_clear_error()
        return runtime._owned_result(
            cls._function(runtime, symbol)(source.pointer), symbol
        )

    def test_numeric_dtype_values_and_native_aliases_match_numpy_125(
        self,
    ) -> None:
        cases = [np.asarray([False, True], dtype=np.bool_)]
        for dtype in (
            np.int8, np.uint8, np.int16, np.uint16,
            np.int32, np.uint32, np.int64, np.uint64,
        ):
            info = np.iinfo(dtype)
            values = (
                [info.min, -1, 0, 1, info.max]
                if np.issubdtype(dtype, np.signedinteger)
                else [0, 1, info.max]
            )
            cases.append(np.asarray(values, dtype=dtype))
        real_values = np.asarray(
            [-np.inf, -1.0, -0.0, 0.0, 1.0, np.inf, np.nan]
        )
        cases.extend(
            real_values.astype(dtype)
            for dtype in (np.float16, np.float32, np.float64)
        )
        complex_values = np.asarray(
            [
                0.0 + 0.0j,
                complex(-0.0, -0.0),
                1.0 + 2.0j,
                -3.0 + 4.0j,
                complex(np.inf, -np.inf),
                complex(np.nan, 1.0),
                complex(1.0, np.nan),
            ]
        )
        cases.extend(
            complex_values.astype(dtype)
            for dtype in (np.complex64, np.complex128)
        )
        native_cases = (
            (
                8,
                np.asarray(
                    [np.iinfo(np.int64).min, -1, 0, 1,
                     np.iinfo(np.int64).max],
                    dtype=np.int64,
                ),
            ),
            (
                9,
                np.asarray(
                    [0, 1, np.iinfo(np.uint64).max],
                    dtype=np.uint64,
                ),
            ),
            (14, real_values.astype(np.longdouble)),
            (17, complex_values.astype(np.clongdouble)),
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for symbol in self._SYMBOLS:
                for values in cases:
                    with self.subTest(
                        symbol=symbol, dtype=str(values.dtype)
                    ):
                        expected = np.conjugate(values)
                        with runtime.from_numpy(values) as source, self._call(
                            runtime, symbol, source
                        ) as actual:
                            self.assertEqual(
                                expected.dtype, actual.numpy_dtype
                            )
                            self.assertEqual(
                                expected.tobytes(order="C"),
                                NegativePositiveSemanticsTests._logical_bytes(
                                    runtime, actual
                                ),
                            )
                for dtype_number, values in native_cases:
                    with self.subTest(
                        symbol=symbol, dtype_number=dtype_number
                    ):
                        expected = np.conjugate(values)
                        with SpacingSemanticsTests._from_numpy_as(
                            runtime, values, dtype_number
                        ) as source, self._call(
                            runtime, symbol, source
                        ) as actual:
                            self.assertEqual(
                                dtype_number, actual.dtype_number
                            )
                            self.assertEqual(
                                expected.tobytes(order="C"),
                                NegativePositiveSemanticsTests._logical_bytes(
                                    runtime, actual
                                ),
                            )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_float_and_complex_bits_match_numpy_125(self) -> None:
        half_bits = np.arange(1 << 16, dtype=np.uint16)
        patterns32 = np.asarray(
            [
                0x00000000,
                0x80000000,
                0x3F800000,
                0xBF800000,
                0x7F800000,
                0xFF800000,
                0x7F800001,
                0xFFC00002,
                0x00800000,
                0x00000001,
            ],
            dtype=np.uint32,
        )
        patterns64 = np.asarray(
            [
                0x0000000000000000,
                0x8000000000000000,
                0x3FF0000000000000,
                0xBFF0000000000000,
                0x7FF0000000000000,
                0xFFF0000000000000,
                0x7FF0000000000001,
                0xFFF8000000000002,
                0x0010000000000000,
                0x0000000000000001,
            ],
            dtype=np.uint64,
        )
        complex32_components = np.stack(
            (patterns32, np.roll(patterns32, 3)), axis=1
        )
        complex64_components = np.stack(
            (patterns64, np.roll(patterns64, 3)), axis=1
        )
        cases = (
            half_bits.view(np.float16),
            patterns32.view(np.float32),
            patterns64.view(np.float64),
            complex32_components.reshape(-1).view(np.complex64),
            complex64_components.reshape(-1).view(np.complex128),
        )
        native_cases = (
            (14, patterns64.view(np.longdouble)),
            (
                17,
                complex64_components.reshape(-1).view(np.clongdouble),
            ),
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for symbol in self._SYMBOLS:
                for values in cases:
                    with self.subTest(
                        symbol=symbol, dtype=str(values.dtype)
                    ):
                        expected = np.conjugate(values)
                        with runtime.from_numpy(values) as source, self._call(
                            runtime, symbol, source
                        ) as actual:
                            self.assertEqual(
                                expected.tobytes(order="C"),
                                NegativePositiveSemanticsTests._logical_bytes(
                                    runtime, actual
                                ),
                            )
                for dtype_number, values in native_cases:
                    with self.subTest(
                        symbol=symbol, dtype_number=dtype_number
                    ):
                        expected = np.conjugate(values)
                        with SpacingSemanticsTests._from_numpy_as(
                            runtime, values, dtype_number
                        ) as source, self._call(
                            runtime, symbol, source
                        ) as actual:
                            self.assertEqual(
                                expected.tobytes(order="C"),
                                NegativePositiveSemanticsTests._logical_bytes(
                                    runtime, actual
                                ),
                            )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_layout_lifetime_and_repeated_calls_match_numpy_125(self) -> None:
        class CnpSlice(ctypes.Structure):
            _fields_ = [
                ("start", ctypes.c_int64),
                ("stop", ctypes.c_int64),
                ("step", ctypes.c_int64),
                ("has_start", ctypes.c_bool),
                ("has_stop", ctypes.c_bool),
                ("has_step", ctypes.c_bool),
            ]

        scalar_values = np.asarray(complex(-0.0, -0.0), dtype=np.complex64)
        empty_values = np.empty((2, 0, 3), dtype=np.complex128)
        base_values = (
            np.arange(24, dtype=np.float64).reshape(4, 6)
            + 1j * np.arange(-12, 12, dtype=np.float64).reshape(4, 6)
        ).astype(np.complex128)
        strided_values = base_values[::2, ::-2]
        fortran_values = np.asfortranarray(
            np.asarray(
                [
                    [complex(1.0, -0.0), complex(-2.0, 3.0)],
                    [complex(np.nan, 1.0), complex(np.inf, -np.inf)],
                    [complex(-0.0, np.nan), complex(4.0, -5.0)],
                ],
                dtype=np.complex64,
            )
        )
        broadcast_base = (
            np.arange(12, dtype=np.float32).reshape(3, 4)
            + 1j * np.arange(-6, 6, dtype=np.float32).reshape(3, 4)
        ).astype(np.complex64)
        broadcast_values = np.broadcast_to(
            broadcast_base, (2, 3, 4)
        ).transpose(2, 0, 1)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            slice_function = runtime.dll.cnp_array_slice
            slice_function.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.POINTER(CnpSlice),
            ]
            slice_function.restype = ctypes.c_void_p

            for symbol in self._SYMBOLS:
                for values in (scalar_values, empty_values):
                    with self.subTest(symbol=symbol, shape=values.shape):
                        expected = np.conjugate(values)
                        with runtime.from_numpy(values) as source, self._call(
                            runtime, symbol, source
                        ) as actual:
                            self.assertEqual(expected.shape, actual.shape)
                            self.assertEqual(
                                expected.tobytes(order="C"),
                                NegativePositiveSemanticsTests._logical_bytes(
                                    runtime, actual
                                ),
                            )

                base = runtime.from_numpy(base_values)
                slices = (CnpSlice * 2)(
                    CnpSlice(0, 0, 2, False, False, True),
                    CnpSlice(0, 0, -2, False, False, True),
                )
                source = runtime._owned_result(
                    slice_function(base.pointer, 2, slices),
                    "cnp_array_slice",
                )
                base.close()
                actual = self._call(runtime, symbol, source)
                source.close()
                with actual:
                    expected = np.conjugate(strided_values)
                    self.assertEqual(
                        expected.tobytes(order="C"),
                        NegativePositiveSemanticsTests._logical_bytes(
                            runtime, actual
                        ),
                    )
                    self.assertEqual(expected.strides, actual.strides)

                stored = runtime.from_numpy(fortran_values.T)
                source = runtime.transpose(stored, (1, 0))
                stored.close()
                actual = self._call(runtime, symbol, source)
                source.close()
                with actual:
                    expected = np.conjugate(fortran_values)
                    self.assertEqual(
                        expected.tobytes(order="C"),
                        NegativePositiveSemanticsTests._logical_bytes(
                            runtime, actual
                        ),
                    )
                    self.assertEqual(expected.strides, actual.strides)

                base = runtime.from_numpy(broadcast_base)
                expander = runtime.from_numpy(
                    np.zeros((2, 1, 1), dtype=np.complex64)
                )
                broadcasted = runtime.broadcast_arrays((base, expander))
                source = runtime.transpose(broadcasted[0], (2, 0, 1))
                base.close()
                expander.close()
                broadcasted[0].close()
                broadcasted[1].close()
                actual = self._call(runtime, symbol, source)
                source.close()
                with actual:
                    expected = np.conjugate(broadcast_values)
                    self.assertEqual(
                        expected.tobytes(order="C"),
                        NegativePositiveSemanticsTests._logical_bytes(
                            runtime, actual
                        ),
                    )
                    self.assertEqual(expected.strides, actual.strides)

                with runtime.from_numpy(
                    base_values.reshape(-1)
                ) as source:
                    before_calls = runtime.retained_bytes
                    for _ in range(128):
                        with self._call(runtime, symbol, source):
                            pass
                    self.assertEqual(
                        before_calls, runtime.retained_bytes
                    )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_unsupported_dtypes_and_null_input_are_explicit(self) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            array_new = runtime.dll.cnp_array_new
            array_new.argtypes = [
                ctypes.c_int,
                ctypes.POINTER(ctypes.c_int64),
                ctypes.c_int,
                ctypes.c_int,
            ]
            array_new.restype = ctypes.c_void_p
            shape = (ctypes.c_int64 * 1)(2)
            for symbol in self._SYMBOLS:
                function = self._function(runtime, symbol)
                for dtype_number in (18, 19, 20, 21, 22, 23):
                    with self.subTest(
                        symbol=symbol, dtype_number=dtype_number
                    ), runtime._owned_result(
                        array_new(1, shape, dtype_number, 0),
                        "cnp_array_new",
                    ) as source:
                        runtime.dll.cnp_clear_error()
                        pointer = function(source.pointer)
