    def test_real_and_complex_bits_match_numpy_125(self) -> None:
        half_bits = np.arange(1 << 16, dtype=np.uint16)
        half_pi32 = np.asarray(np.pi / 2.0, dtype=np.float32)
        half_pi64 = np.asarray(np.pi / 2.0, dtype=np.float64)
        patterns32 = np.asarray(
            [
                0x00000000,
                0x80000000,
                0x3F800000,
                0xBF800000,
                0x7F800000,
                0xFF800000,
                0x7F800001,
                0x7FC00002,
                0xFF800003,
                0xFFC00004,
                0x00800000,
                0x00000001,
                np.nextafter(
                    half_pi32, np.float32(-np.inf), dtype=np.float32
                ).view(np.uint32).item(),
                half_pi32.view(np.uint32).item(),
                np.nextafter(
                    half_pi32, np.float32(np.inf), dtype=np.float32
                ).view(np.uint32).item(),
                (-half_pi32).view(np.uint32).item(),
                np.asarray(1e10, dtype=np.float32).view(np.uint32).item(),
                np.asarray(-1e10, dtype=np.float32).view(np.uint32).item(),
                0x7F7FFFFF,
                0xFF7FFFFF,
            ],
            dtype=np.uint32,
        )
        patterns64 = np.asarray(
            [
                0x0000000000000000,
                0x8000000000000000,
                0x3FF0000000000000,
                0xBFF0000000000000,
                0x7FF0000000000000,
                0xFFF0000000000000,
                0x7FF0000000000001,
                0x7FF8000000000002,
                0xFFF0000000000003,
                0xFFF8000000000004,
                0x0010000000000000,
                0x0000000000000001,
                np.nextafter(
                    half_pi64, np.float64(-np.inf), dtype=np.float64
                ).view(np.uint64).item(),
                half_pi64.view(np.uint64).item(),
                np.nextafter(
                    half_pi64, np.float64(np.inf), dtype=np.float64
                ).view(np.uint64).item(),
                (-half_pi64).view(np.uint64).item(),
                np.asarray(1e20, dtype=np.float64).view(np.uint64).item(),
                np.asarray(-1e20, dtype=np.float64).view(np.uint64).item(),
                0x7FEFFFFFFFFFFFFF,
                0xFFEFFFFFFFFFFFFF,
            ],
            dtype=np.uint64,
        )
        complex32_components = np.asarray(
            [
                (real, imaginary)
                for real in patterns32
                for imaginary in patterns32
            ],
            dtype=np.uint32,
        )
        complex64_components = np.asarray(
            [
                (real, imaginary)
                for real in patterns64
                for imaginary in patterns64
            ],
            dtype=np.uint64,
        )
        cases = (
            half_bits.view(np.float16),
            patterns32.view(np.float32),
            patterns64.view(np.float64),
            complex32_components.reshape(-1).view(np.complex64),
            complex64_components.reshape(-1).view(np.complex128),
        )
        native_cases = (
            (14, patterns64.view(np.longdouble)),
            (
                17,
                complex64_components.reshape(-1).view(np.clongdouble),
            ),
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for values in cases:
                with self.subTest(
                    dtype=str(values.dtype)
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.tan(values)
                    with runtime.from_numpy(values) as source, self._call(
                        runtime, source
                    ) as actual:
                        self.assertEqual(expected.dtype, actual.numpy_dtype)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )
            for dtype_number, values in native_cases:
                with self.subTest(
                    dtype_number=dtype_number
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.tan(values)
                    with SpacingSemanticsTests._from_numpy_as(
                        runtime, values, dtype_number
                    ) as source, self._call(runtime, source) as actual:
                        self.assertEqual(dtype_number, actual.dtype_number)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )
            self.assertEqual(baseline, runtime.retained_bytes)


