class Arctan2SemanticsTests(unittest.TestCase):
    _REAL_DTYPES = (
        np.bool_,
        np.int8,
        np.uint8,
        np.int16,
        np.uint16,
        np.int32,
        np.uint32,
        np.int64,
        np.uint64,
        np.float16,
        np.float32,
        np.float64,
    )

    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_arctan2
        function.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    @classmethod
    def _call(cls, runtime: CnumpyRuntime, y, x):
        runtime.dll.cnp_clear_error()
        return runtime._owned_result(
            cls._function(runtime)(y.pointer, x.pointer), "cnp_arctan2"
        )

    @staticmethod
    def _values(dtype, *, numerator: bool) -> np.ndarray:
        resolved = np.dtype(dtype)
        if resolved.kind == "b":
            values = [False, True, True]
        elif resolved.kind == "u":
            maximum = np.iinfo(resolved).max
            values = [0, 1, 3, maximum]
        elif resolved.kind == "i":
            info = np.iinfo(resolved)
            values = [info.min, -3, -1, 0, 1, 3, info.max]
        else:
            values = (
                [-np.inf, -3.0, -1.0, -0.0, 0.0,
                 1.0, 3.0, np.inf, np.nan]
                if numerator
                else [-np.inf, -2.0, -0.0, 0.0, 2.0, np.inf, np.nan]
            )
        return np.asarray(values, dtype=resolved)

    def test_real_dtype_loop_resolution_and_values_match_numpy_125(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for y_dtype in self._REAL_DTYPES:
                y_values = self._values(y_dtype, numerator=True)
                for x_dtype in self._REAL_DTYPES:
                    x_values = self._values(x_dtype, numerator=False)
                    length = max(y_values.size, x_values.size)
                    y = np.resize(y_values, length)
                    x = np.resize(x_values, length)
                    with self.subTest(
                        y_dtype=np.dtype(y_dtype).name,
                        x_dtype=np.dtype(x_dtype).name,
                    ), warnings.catch_warnings():
                        warnings.simplefilter("ignore")
                        expected = np.arctan2(y, x)
                        with runtime.from_numpy(y) as y_source, \
                                runtime.from_numpy(x) as x_source, \
                                self._call(
                                    runtime, y_source, x_source
                                ) as actual:
                            self.assertEqual(
                                expected.dtype, actual.numpy_dtype
                            )
                            AroundSemanticsTests._assert_matches_numpy(
                                expected, actual.to_numpy()
                            )

            native_cases = (
                (
                    8,
                    13,
                    np.asarray(
                        [np.iinfo(np.int64).min, -1, 0, 1,
                         np.iinfo(np.int64).max],
                        dtype=np.int64,
                    ),
                    np.asarray([-1, -0.0, 0.0, 1, 2], dtype=np.int64),
                ),
                (
                    9,
                    13,
                    np.asarray(
                        [0, 1, 3, np.iinfo(np.uint64).max],
                        dtype=np.uint64,
                    ),
                    np.asarray([0, 1, 2, 3], dtype=np.uint64),
                ),
                (
                    14,
                    14,
                    np.asarray(
                        [-np.inf, -1.0, -0.0, 0.0, 1.0, np.inf, np.nan],
                        dtype=np.longdouble,
                    ),
                    np.asarray(
                        [-2.0, -0.0, 0.0, 2.0, -np.inf, np.inf, np.nan],
                        dtype=np.longdouble,
                    ),
                ),
            )
            for dtype_number, result_dtype, y, x in native_cases:
                with self.subTest(
                    native_dtype=dtype_number
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.arctan2(y, x)
                    with SpacingSemanticsTests._from_numpy_as(
                        runtime, y, dtype_number
                    ) as y_source, SpacingSemanticsTests._from_numpy_as(
                        runtime, x, dtype_number
                    ) as x_source, self._call(
                        runtime, y_source, x_source
                    ) as actual:
                        self.assertEqual(result_dtype, actual.dtype_number)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_half_and_directed_float_bits_match_numpy_125(self) -> None:
        all_half = np.arange(1 << 16, dtype=np.uint16).view(np.float16)
        fixed_half = np.asarray(
            [
                0x0000, 0x8000, 0x3C00, 0xBC00,
                0x7C00, 0xFC00, 0x7C01, 0x7E02,
                0xFC03, 0xFE04, 0x0001, 0x03FF,
                0x7BFF, 0xFBFF,
            ],
            dtype=np.uint16,
        ).view(np.float16)

        one32 = np.asarray(1.0, dtype=np.float32)
        one64 = np.asarray(1.0, dtype=np.float64)
        patterns32 = np.asarray(
            [
                0x00000000, 0x80000000, 0x3F800000, 0xBF800000,
                np.nextafter(
                    one32, np.float32(-np.inf), dtype=np.float32
                ).view(np.uint32).item(),
                np.nextafter(
                    one32, np.float32(np.inf), dtype=np.float32
                ).view(np.uint32).item(),
                0x7F800000, 0xFF800000,
                0x7F800001, 0x7FC00002,
                0xFF800003, 0xFFC00004,
                0x00800000, 0x00000001,
                np.asarray(3.0, dtype=np.float32).view(np.uint32).item(),
                np.asarray(-3.0, dtype=np.float32).view(np.uint32).item(),
                0x7F7FFFFF, 0xFF7FFFFF,
            ],
            dtype=np.uint32,
        )
        patterns64 = np.asarray(
            [
                0x0000000000000000, 0x8000000000000000,
                0x3FF0000000000000, 0xBFF0000000000000,
                np.nextafter(
                    one64, np.float64(-np.inf), dtype=np.float64
                ).view(np.uint64).item(),
                np.nextafter(
                    one64, np.float64(np.inf), dtype=np.float64
                ).view(np.uint64).item(),
                0x7FF0000000000000, 0xFFF0000000000000,
                0x7FF0000000000001, 0x7FF8000000000002,
                0xFFF0000000000003, 0xFFF8000000000004,
                0x0010000000000000, 0x0000000000000001,
                np.asarray(3.0, dtype=np.float64).view(np.uint64).item(),
                np.asarray(-3.0, dtype=np.float64).view(np.uint64).item(),
                0x7FEFFFFFFFFFFFFF, 0xFFEFFFFFFFFFFFFF,
            ],
            dtype=np.uint64,
        )

        cases: list[tuple[np.ndarray, np.ndarray]] = []
        for fixed in fixed_half:
            cases.append((all_half, np.full(all_half.shape, fixed)))
            cases.append((np.full(all_half.shape, fixed), all_half))
        for patterns, dtype in (
            (patterns32, np.float32),
            (patterns64, np.float64),
        ):
            components = patterns.view(dtype)
            y, x = np.meshgrid(components, components, indexing="ij")
            cases.append((y.reshape(-1), x.reshape(-1)))

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for case_index, (y, x) in enumerate(cases):
                with self.subTest(
                    case_index=case_index, dtype=str(y.dtype)
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.arctan2(y, x)
                    with runtime.from_numpy(y) as y_source, \
                            runtime.from_numpy(x) as x_source, \
                            self._call(
                                runtime, y_source, x_source
                            ) as actual:
                        self.assertEqual(expected.dtype, actual.numpy_dtype)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )

            native_values = patterns64.view(np.longdouble)
            y, x = np.meshgrid(
                native_values, native_values, indexing="ij"
            )
            y = y.reshape(-1)
            x = x.reshape(-1)
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                expected = np.arctan2(y, x)
            with SpacingSemanticsTests._from_numpy_as(
                runtime, y, 14
            ) as y_source, SpacingSemanticsTests._from_numpy_as(
                runtime, x, 14
            ) as x_source, self._call(
                runtime, y_source, x_source
            ) as actual:
                self.assertEqual(14, actual.dtype_number)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_broadcast_layout_lifetime_and_repeated_calls_match_numpy_125(
        self,
    ) -> None:
        class CnpSlice(ctypes.Structure):
            _fields_ = [
                ("start", ctypes.c_int64),
                ("stop", ctypes.c_int64),
                ("step", ctypes.c_int64),
                ("has_start", ctypes.c_bool),
                ("has_stop", ctypes.c_bool),
                ("has_step", ctypes.c_bool),
            ]

        cases = (
            (
                np.asarray(-0.0, dtype=np.float32),
                np.asarray(-0.0, dtype=np.float32),
            ),
            (
                np.empty((2, 0, 3), dtype=np.float64),
                np.empty((1, 0, 1), dtype=np.float64),
            ),
            (
                np.arange(-6, 0, dtype=np.float32).reshape(2, 1, 3),
                np.arange(1, 5, dtype=np.float32).reshape(1, 4, 1),
            ),
        )
        fortran_y = np.asfortranarray(
            np.asarray(
                [[-0.0, 1.0, -1.0], [2.0, -2.0, np.nan]],
                dtype=np.float64,
            )
        )
        fortran_x = np.asfortranarray(
            np.asarray(
                [[-0.0, -1.0, -1.0], [np.inf, -np.inf, 1.0]],
                dtype=np.float64,
            )
        )
        base_y = np.arange(-12, 12, dtype=np.float64).reshape(4, 6)
        base_x = np.arange(1, 25, dtype=np.float64).reshape(4, 6)
        expected_y_view = base_y[::2, ::-2]
        expected_x_view = base_x[::2, ::-2]

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for y, x in cases:
                with self.subTest(y_shape=y.shape, x_shape=x.shape):
                    expected = np.arctan2(y, x)
                    with runtime.from_numpy(y) as y_source, \
                            runtime.from_numpy(x) as x_source:
                        actual = self._call(runtime, y_source, x_source)
                    with actual:
                        self.assertEqual(expected.shape, actual.shape)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )

            stored_y = runtime.from_numpy(fortran_y.T)
            stored_x = runtime.from_numpy(fortran_x.T)
            y_source = runtime.transpose(stored_y, (1, 0))
            x_source = runtime.transpose(stored_x, (1, 0))
            stored_y.close()
            stored_x.close()
            actual = self._call(runtime, y_source, x_source)
            y_source.close()
            x_source.close()
            with actual:
                expected = np.arctan2(fortran_y, fortran_x)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )
                self.assertEqual(expected.strides, actual.strides)

            slice_function = runtime.dll.cnp_array_slice
            slice_function.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.POINTER(CnpSlice),
            ]
            slice_function.restype = ctypes.c_void_p
            slices = (CnpSlice * 2)(
                CnpSlice(0, 0, 2, False, False, True),
                CnpSlice(0, 0, -2, False, False, True),
            )
            y_base = runtime.from_numpy(base_y)
            x_base = runtime.from_numpy(base_x)
            y_source = runtime._owned_result(
                slice_function(y_base.pointer, 2, slices),
                "cnp_array_slice",
            )
            x_source = runtime._owned_result(
                slice_function(x_base.pointer, 2, slices),
                "cnp_array_slice",
            )
            y_base.close()
            x_base.close()
            actual = self._call(runtime, y_source, x_source)
            y_source.close()
            x_source.close()
            with actual:
                expected = np.arctan2(expected_y_view, expected_x_view)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )

            with runtime.from_numpy(base_y) as y_source, \
                    runtime.from_numpy(base_x) as x_source:
                before_calls = runtime.retained_bytes
                for _ in range(128):
                    with self._call(runtime, y_source, x_source):
                        pass
                self.assertEqual(before_calls, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_invalid_inputs_are_explicit_and_do_not_retain_memory(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            real = np.asarray([1.0], dtype=np.float64)

            with runtime.from_numpy(real) as valid_source:
                for y_pointer, x_pointer in (
                    (None, None),
                    (None, valid_source.pointer),
                    (valid_source.pointer, None),
                ):
                    with self.subTest(
                        y_null=y_pointer is None, x_null=x_pointer is None
                    ):
                        runtime.dll.cnp_clear_error()
                        pointer = function(y_pointer, x_pointer)
                        if pointer:
                            runtime.dll.cnp_array_decref(pointer)
                        self.assertFalse(pointer)
                        error = runtime.error_state()
                        self.assertEqual(-1, error.status)
                        self.assertEqual("cnp_arctan2", error.function)
                        self.assertIn("arrays", error.message)

            unsupported = (
                np.asarray([1.0 + 2.0j], dtype=np.complex64),
                np.asarray([1.0 + 2.0j], dtype=np.complex128),
            )
            for values in unsupported:
                for unsupported_is_y in (False, True):
                    with self.subTest(
                        dtype=str(values.dtype),
                        unsupported_is_y=unsupported_is_y,
                    ), runtime.from_numpy(values) as unsupported_source, \
                            runtime.from_numpy(real) as real_source:
                        y_source = (
                            unsupported_source
                            if unsupported_is_y else real_source
                        )
                        x_source = (
                            real_source
                            if unsupported_is_y else unsupported_source
                        )
                        runtime.dll.cnp_clear_error()
                        pointer = function(
                            y_source.pointer, x_source.pointer
                        )
                        if pointer:
                            runtime.dll.cnp_array_decref(pointer)
                        self.assertFalse(pointer)
                        error = runtime.error_state()
                        self.assertEqual(-3, error.status)
                        self.assertEqual("cnp_arctan2", error.function)
                        self.assertIn("does not support", error.message)

            array_new = runtime.dll.cnp_array_new
            array_new.argtypes = [
                ctypes.c_int,
                ctypes.POINTER(ctypes.c_int64),
                ctypes.c_int,
                ctypes.c_int,
            ]
            array_new.restype = ctypes.c_void_p
            shape = (ctypes.c_int64 * 1)(1)
            with runtime.from_numpy(real) as real_source:
                for dtype_number in (15, 16, 17, 18, 19, 20, 21, 22, 23):
                    with self.subTest(
                        native_unsupported_dtype=dtype_number
                    ), runtime._owned_result(
                        array_new(1, shape, dtype_number, 0),
                        "cnp_array_new",
                    ) as unsupported_source:
                        for unsupported_is_y in (False, True):
                            y_source = (
                                unsupported_source
                                if unsupported_is_y else real_source
                            )
                            x_source = (
                                real_source
                                if unsupported_is_y else unsupported_source
                            )
                            runtime.dll.cnp_clear_error()
                            pointer = function(
                                y_source.pointer, x_source.pointer
                            )
                            if pointer:
                                runtime.dll.cnp_array_decref(pointer)
                            self.assertFalse(pointer)
                            error = runtime.error_state()
                            self.assertEqual(-3, error.status)
                            self.assertEqual(
                                "cnp_arctan2", error.function
                            )
                            self.assertIn(
                                "does not support", error.message
                            )

            with runtime.from_numpy(
                np.zeros((2, 3), dtype=np.float64)
            ) as y_source, runtime.from_numpy(
                np.zeros((4,), dtype=np.float64)
            ) as x_source:
                runtime.dll.cnp_clear_error()
                pointer = function(y_source.pointer, x_source.pointer)
                if pointer:
                    runtime.dll.cnp_array_decref(pointer)
                self.assertFalse(pointer)
                error = runtime.error_state()
                self.assertEqual(-7, error.status)
                self.assertEqual("cnp_arctan2", error.function)
                self.assertIn("broadcast", error.message)
            self.assertEqual(baseline, runtime.retained_bytes)


class HypotSemanticsTests(unittest.TestCase):
    _REAL_DTYPES = Arctan2SemanticsTests._REAL_DTYPES

    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_hypot
        function.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    @classmethod
    def _call(cls, runtime: CnumpyRuntime, x, y):
        runtime.dll.cnp_clear_error()
        return runtime._owned_result(
            cls._function(runtime)(x.pointer, y.pointer), "cnp_hypot"
        )

    @staticmethod
    def _values(dtype) -> np.ndarray:
        resolved = np.dtype(dtype)
        if resolved.kind == "b":
            values = [False, True]
        elif resolved.kind == "u":
            maximum = np.iinfo(resolved).max
            values = [0, 1, 3, maximum]
        elif resolved.kind == "i":
            info = np.iinfo(resolved)
            values = [info.min, -3, -1, 0, 1, 3, info.max]
        else:
            values = [
                -np.inf, -3.0, -1.0, -0.0, 0.0,
                1.0, 3.0, np.inf, np.nan,
            ]
        return np.asarray(values, dtype=resolved)

    def test_low_precision_real_inputs_use_numpy_125_half_loop(self) -> None:
        x_values = np.asarray([3, 5, 8], dtype=np.int8)
        y_values = np.asarray([4, 12, 15], dtype=np.uint8)
        expected = np.hypot(x_values, y_values)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            with runtime.from_numpy(x_values) as x_source, \
                    runtime.from_numpy(y_values) as y_source:
                pointer = self._function(runtime)(
                    x_source.pointer, y_source.pointer
                )
                with runtime._owned_result(pointer, "cnp_hypot") as actual:
                    self.assertEqual(expected.dtype, actual.numpy_dtype)
                    self.assertEqual(
                        expected.tobytes(order="C"),
                        NegativePositiveSemanticsTests._logical_bytes(
                            runtime, actual
                        ),
                    )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_real_dtype_loop_resolution_and_values_match_numpy_125(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for x_dtype in self._REAL_DTYPES:
                x_values = self._values(x_dtype)
                for y_dtype in self._REAL_DTYPES:
                    y_values = self._values(y_dtype)
                    length = max(x_values.size, y_values.size)
                    x = np.resize(x_values, length)
                    y = np.resize(y_values, length)
                    with self.subTest(
                        x_dtype=np.dtype(x_dtype).name,
                        y_dtype=np.dtype(y_dtype).name,
                    ), warnings.catch_warnings():
                        warnings.simplefilter("ignore")
                        expected = np.hypot(x, y)
                        with runtime.from_numpy(x) as x_source, \
                                runtime.from_numpy(y) as y_source, \
                                self._call(
                                    runtime, x_source, y_source
                                ) as actual:
                            self.assertEqual(
                                expected.dtype, actual.numpy_dtype
                            )
                            self.assertEqual(
                                expected.tobytes(order="C"),
                                NegativePositiveSemanticsTests._logical_bytes(
                                    runtime, actual
                                ),
                            )
            self.assertEqual(baseline, runtime.retained_bytes)

