    def test_layout_lifetime_and_repeated_calls_match_numpy_125(self) -> None:
        class CnpSlice(ctypes.Structure):
            _fields_ = [
                ("start", ctypes.c_int64),
                ("stop", ctypes.c_int64),
                ("step", ctypes.c_int64),
                ("has_start", ctypes.c_bool),
                ("has_stop", ctypes.c_bool),
                ("has_step", ctypes.c_bool),
            ]

        cases = (
            np.asarray(-0.0, dtype=np.float32),
            np.empty((2, 0, 3), dtype=np.float64),
            np.asarray(
                [[-3.0, -1.0, -0.0], [0.0, 1.0, 3.0]],
                dtype=np.float32,
            ),
        )
        fortran_values = np.asfortranarray(
            np.asarray(
                [
                    [complex(-3.0, 0.5), complex(-1.0, -2.0)],
                    [complex(-0.0, 0.0), complex(1.0, 3.0)],
                ],
                dtype=np.complex128,
            )
        )
        base_values = np.arange(-12, 12, dtype=np.float64).reshape(4, 6)
        complex_base_values = (
            base_values + 1j * np.arange(12, -12, -1).reshape(4, 6)
        ).astype(np.complex128)
        expected_view = complex_base_values[::2, ::-2]

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for values in cases:
                with self.subTest(
                    shape=values.shape
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.sinh(values)
                    with runtime.from_numpy(values) as source:
                        actual = self._call(runtime, source)
                    with actual:
                        self.assertEqual(expected.shape, actual.shape)
                        self.assertEqual(expected.strides, actual.strides)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )

            stored = runtime.from_numpy(fortran_values.T)
            source = runtime.transpose(stored, (1, 0))
            stored.close()
            actual = self._call(runtime, source)
            source.close()
            with actual, warnings.catch_warnings():
                warnings.simplefilter("ignore")
                expected = np.sinh(fortran_values)
                self.assertEqual(expected.strides, actual.strides)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )

            slice_function = runtime.dll.cnp_array_slice
            slice_function.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.POINTER(CnpSlice),
            ]
            slice_function.restype = ctypes.c_void_p
            slices = (CnpSlice * 2)(
                CnpSlice(0, 0, 2, False, False, True),
                CnpSlice(0, 0, -2, False, False, True),
            )
            base = runtime.from_numpy(complex_base_values)
            source = runtime._owned_result(
                slice_function(base.pointer, 2, slices),
                "cnp_array_slice",
            )
            base.close()
            actual = self._call(runtime, source)
            source.close()
            with actual:
                expected = np.sinh(expected_view)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )

            with runtime.from_numpy(base_values) as source:
                before_calls = runtime.retained_bytes
                for _ in range(64):
                    with self._call(runtime, source):
                        pass
                self.assertEqual(before_calls, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)


    def test_invalid_inputs_are_explicit_and_do_not_retain_memory(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            runtime.dll.cnp_clear_error()
            pointer = function(None)
            if pointer:
                runtime.dll.cnp_array_decref(pointer)
            self.assertFalse(pointer)
            error = runtime.error_state()
            self.assertEqual(-1, error.status)
            self.assertEqual("cnp_sinh", error.function)
            self.assertIn("source array", error.message)

            array_new = runtime.dll.cnp_array_new
            array_new.argtypes = [
                ctypes.c_int,
                ctypes.POINTER(ctypes.c_int64),
                ctypes.c_int,
                ctypes.c_int,
            ]
            array_new.restype = ctypes.c_void_p
            shape = (ctypes.c_int64 * 1)(1)
            for dtype_number in (18, 19, 20, 21, 22, 23):
                with self.subTest(
                    native_unsupported_dtype=dtype_number
                ), runtime._owned_result(
                    array_new(1, shape, dtype_number, 0),
                    "cnp_array_new",
                ) as source:
                    runtime.dll.cnp_clear_error()
                    pointer = function(source.pointer)
                    if pointer:
                        runtime.dll.cnp_array_decref(pointer)
                    self.assertFalse(pointer)
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual("cnp_sinh", error.function)
                    self.assertIn("does not support", error.message)
            self.assertEqual(baseline, runtime.retained_bytes)


