class TanhSemanticsTests(unittest.TestCase):
    _REAL_DTYPES = HypotSemanticsTests._REAL_DTYPES

    @staticmethod
    def _function(runtime: CnumpyRuntime):
        function = runtime.dll.cnp_tanh
        function.argtypes = [ctypes.c_void_p]
        function.restype = ctypes.c_void_p
        return function

    @classmethod
    def _call(cls, runtime: CnumpyRuntime, source):
        runtime.dll.cnp_clear_error()
        return runtime._owned_result(
            cls._function(runtime)(source.pointer), "cnp_tanh"
        )

    def test_low_precision_integer_loop_matches_numpy_125(self) -> None:
        values = np.asarray([-3, 0, 1, 5], dtype=np.int8)
        expected = np.tanh(values)
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            with runtime.from_numpy(values) as source, \
                    self._call(runtime, source) as actual:
                self.assertEqual(expected.dtype, actual.numpy_dtype)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_real_dtype_dispatch_and_values_match_numpy_125(self) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for dtype in self._REAL_DTYPES:
                values = HypotSemanticsTests._values(dtype)
                with self.subTest(
                    dtype=np.dtype(dtype).name
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.tanh(values)
                    with runtime.from_numpy(values) as source, \
                            self._call(runtime, source) as actual:
                        self.assertEqual(expected.dtype, actual.numpy_dtype)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )

            native_cases = (
                (
                    8,
                    13,
                    np.asarray(
                        [np.iinfo(np.int64).min, -3, -1, 0, 1, 3,
                         np.iinfo(np.int64).max],
                        dtype=np.int64,
                    ),
                ),
                (
                    9,
                    13,
                    np.asarray(
                        [0, 1, 3, np.iinfo(np.uint64).max],
                        dtype=np.uint64,
                    ),
                ),
                (
                    14,
                    14,
                    np.asarray(
                        [-np.inf, -3.0, -1.0, -0.0, 0.0,
                         1.0, 3.0, np.inf, np.nan],
                        dtype=np.longdouble,
                    ),
                ),
            )
            for dtype_number, result_dtype, values in native_cases:
                with self.subTest(
                    native_dtype=dtype_number
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.tanh(values)
                    with SpacingSemanticsTests._from_numpy_as(
                        runtime, values, dtype_number
                    ) as source, self._call(runtime, source) as actual:
                        self.assertEqual(result_dtype, actual.dtype_number)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_half_and_directed_real_bits_match_numpy_125(self) -> None:
        all_half = np.arange(1 << 16, dtype=np.uint16).view(np.float16)
        saturation32 = np.float32(
            np.arctanh(
                np.nextafter(np.float32(1.0), np.float32(0.0))
            )
        )
        saturation64 = np.float64(
            np.arctanh(
                np.nextafter(np.float64(1.0), np.float64(0.0))
            )
        )
        patterns32 = np.asarray(
            [
                0x00000000, 0x80000000,
                0x3F800000, 0xBF800000,
                0x3F7FFFFF, 0x3F800001,
                0x7F800000, 0xFF800000,
                0x7F800001, 0x7FC00002,
                0xFF800003, 0xFFC00004,
                0x00800000, 0x80800000,
                0x00000001, 0x80000001,
            ],
            dtype=np.uint32,
        ).view(np.float32)
        patterns64 = np.asarray(
            [
                0x0000000000000000, 0x8000000000000000,
                0x3FF0000000000000, 0xBFF0000000000000,
                0x3FEFFFFFFFFFFFFF, 0x3FF0000000000001,
                0x7FF0000000000000, 0xFFF0000000000000,
                0x7FF0000000000001, 0x7FF8000000000002,
                0xFFF0000000000003, 0xFFF8000000000004,
                0x0010000000000000, 0x8010000000000000,
                0x0000000000000001, 0x8000000000000001,
            ],
            dtype=np.uint64,
        ).view(np.float64)
        patterns32 = np.concatenate(
            (
                patterns32,
                np.asarray(
                    [
                        -saturation32,
                        saturation32,
                        np.nextafter(
                            saturation32, np.float32(-np.inf)
                        ),
                        np.nextafter(
                            saturation32, np.float32(np.inf)
                        ),
                    ],
                    dtype=np.float32,
                ),
            )
        )
        patterns64 = np.concatenate(
            (
                patterns64,
                np.asarray(
                    [
                        -saturation64,
                        saturation64,
                        np.nextafter(
                            saturation64, np.float64(-np.inf)
                        ),
                        np.nextafter(
                            saturation64, np.float64(np.inf)
                        ),
                    ],
                    dtype=np.float64,
                ),
            )
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for values in (all_half, patterns32, patterns64):
                with self.subTest(
                    dtype=str(values.dtype)
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.tanh(values)
                    with runtime.from_numpy(values) as source, \
                            self._call(runtime, source) as actual:
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_layout_lifetime_and_repeated_calls_match_numpy_125(self) -> None:
        class CnpSlice(ctypes.Structure):
            _fields_ = [
                ("start", ctypes.c_int64),
                ("stop", ctypes.c_int64),
                ("step", ctypes.c_int64),
                ("has_start", ctypes.c_bool),
                ("has_stop", ctypes.c_bool),
                ("has_step", ctypes.c_bool),
            ]

        cases = (
            np.asarray(-0.0, dtype=np.float32),
            np.empty((2, 0, 3), dtype=np.float64),
            np.asarray(
                [[-3.0, -1.0, -0.0], [0.0, 1.0, 3.0]],
                dtype=np.float32,
            ),
        )
        fortran_values = np.asfortranarray(
            np.asarray(
                [
                    [complex(-3.0, 0.5), complex(-1.0, -2.0)],
                    [complex(-0.0, 0.0), complex(1.0, 3.0)],
                ],
                dtype=np.complex128,
            )
        )
        base_values = np.arange(-12, 12, dtype=np.float64).reshape(4, 6)
        complex_base_values = (
            base_values + 1j * np.arange(12, -12, -1).reshape(4, 6)
        ).astype(np.complex128)
        expected_view = complex_base_values[::2, ::-2]

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for values in cases:
                with self.subTest(
                    shape=values.shape
                ), warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.tanh(values)
                    with runtime.from_numpy(values) as source:
                        actual = self._call(runtime, source)
                    with actual:
                        self.assertEqual(expected.shape, actual.shape)
                        self.assertEqual(expected.strides, actual.strides)
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )

            stored = runtime.from_numpy(fortran_values.T)
            source = runtime.transpose(stored, (1, 0))
            stored.close()
            actual = self._call(runtime, source)
            source.close()
            with actual, warnings.catch_warnings():
                warnings.simplefilter("ignore")
                expected = np.tanh(fortran_values)
                self.assertEqual(expected.strides, actual.strides)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )

            slice_function = runtime.dll.cnp_array_slice
            slice_function.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.POINTER(CnpSlice),
            ]
            slice_function.restype = ctypes.c_void_p
            slices = (CnpSlice * 2)(
                CnpSlice(0, 0, 2, False, False, True),
                CnpSlice(0, 0, -2, False, False, True),
            )
            base = runtime.from_numpy(complex_base_values)
            source = runtime._owned_result(
                slice_function(base.pointer, 2, slices),
                "cnp_array_slice",
            )
            base.close()
            actual = self._call(runtime, source)
            source.close()
            with actual:
                expected = np.tanh(expected_view)
                self.assertEqual(
                    expected.tobytes(order="C"),
                    NegativePositiveSemanticsTests._logical_bytes(
                        runtime, actual
                    ),
                )

            with runtime.from_numpy(base_values) as source:
                before_calls = runtime.retained_bytes
                for _ in range(64):
                    with self._call(runtime, source):
                        pass
                self.assertEqual(before_calls, runtime.retained_bytes)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_invalid_inputs_are_explicit_and_do_not_retain_memory(
        self,
    ) -> None:
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            runtime.dll.cnp_clear_error()
            pointer = function(None)
            if pointer:
                runtime.dll.cnp_array_decref(pointer)
            self.assertFalse(pointer)
            error = runtime.error_state()
            self.assertEqual(-1, error.status)
            self.assertEqual("cnp_tanh", error.function)
            self.assertIn("source array", error.message)

            array_new = runtime.dll.cnp_array_new
            array_new.argtypes = [
                ctypes.c_int,
                ctypes.POINTER(ctypes.c_int64),
                ctypes.c_int,
                ctypes.c_int,
            ]
            array_new.restype = ctypes.c_void_p
            shape = (ctypes.c_int64 * 1)(1)
            for dtype_number in (18, 19, 20, 21, 22, 23):
                with self.subTest(
                    native_unsupported_dtype=dtype_number
                ), runtime._owned_result(
                    array_new(1, shape, dtype_number, 0),
                    "cnp_array_new",
                ) as source:
                    runtime.dll.cnp_clear_error()
                    pointer = function(source.pointer)
                    if pointer:
                        runtime.dll.cnp_array_decref(pointer)
                    self.assertFalse(pointer)
                    error = runtime.error_state()
                    self.assertEqual(-3, error.status)
                    self.assertEqual("cnp_tanh", error.function)
                    self.assertIn("does not support", error.message)
            self.assertEqual(baseline, runtime.retained_bytes)

