    def test_directed_float_bits_and_boundaries_match_numpy_125(self) -> None:
        base32 = np.asarray(
            [
                0x00000000, 0x80000000,
                0x3F800000, 0xBF800000,
                0x3F7FFFFF, 0x3F800001,
                0x7F800000, 0xFF800000,
                0x7F800001, 0x7FC00002,
                0xFF800003, 0xFFC00004,
                0x00800000, 0x80800000,
                0x00000001, 0x80000001,
                0x7F7FFFFF, 0xFF7FFFFF,
            ],
            dtype=np.uint32,
        ).view(np.float32)
        upper32 = np.float32(88.72283935546875)
        lower32 = np.float32(-103.97208404541015625)
        boundary32 = np.asarray(
            [
                np.nextafter(upper32, np.float32(-np.inf)),
                upper32,
                np.nextafter(upper32, np.float32(np.inf)),
                np.nextafter(lower32, np.float32(-np.inf)),
                lower32,
                np.nextafter(lower32, np.float32(np.inf)),
            ],
            dtype=np.float32,
        )

        base64 = np.asarray(
            [
                0x0000000000000000, 0x8000000000000000,
                0x3FF0000000000000, 0xBFF0000000000000,
                0x3FEFFFFFFFFFFFFF, 0x3FF0000000000001,
                0x7FF0000000000000, 0xFFF0000000000000,
                0x7FF0000000000001, 0x7FF8000000000002,
                0xFFF0000000000003, 0xFFF8000000000004,
                0x0010000000000000, 0x8010000000000000,
                0x0000000000000001, 0x8000000000000001,
                0x7FEFFFFFFFFFFFFF, 0xFFEFFFFFFFFFFFFF,
            ],
            dtype=np.uint64,
        ).view(np.float64)
        upper64 = np.float64(float.fromhex("0x1.62e42fefa39efp+9"))
        lower64 = np.float64(float.fromhex("-0x1.74910d52d3053p+9"))
        boundary64 = np.asarray(
            [
                np.nextafter(upper64, np.float64(-np.inf)),
                upper64,
                np.nextafter(upper64, np.float64(np.inf)),
                np.nextafter(lower64, np.float64(-np.inf)),
                lower64,
                np.nextafter(lower64, np.float64(np.inf)),
            ],
            dtype=np.float64,
        )

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for values in (
                np.concatenate((base32, boundary32)),
                np.concatenate((base64, boundary64)),
            ):
                with self.subTest(dtype=str(values.dtype)), \
                        warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    expected = np.exp(values)
                    with runtime.from_numpy(values) as source, \
                            self._call(runtime, source) as actual:
                        self.assertEqual(
                            expected.tobytes(order="C"),
                            NegativePositiveSemanticsTests._logical_bytes(
                                runtime, actual
                            ),
                        )
            self.assertEqual(baseline, runtime.retained_bytes)

