    @staticmethod
    def _representative_comparison_values(dtype: np.dtype) -> np.ndarray:
        if dtype.kind == "b":
            values = [False, True, True, False]
        elif dtype.kind == "i":
            values = [-3, 0, 7, np.iinfo(dtype).max]
        elif dtype.kind == "u":
            values = [0, 0, 7, np.iinfo(dtype).max]
        elif dtype.kind == "f":
            values = [-3.5, -0.0, 7.25, np.inf]
        else:
            values = [-3 + 1j, complex(-0.0, -0.0), 7.25 + 1j, np.inf + 0j]
        return np.asarray(values, dtype=dtype)

