    def test_pairwise_inputs_and_same_kind_outputs_match_numpy_125(
        self,
    ) -> None:
        dtypes = (
            np.bool_,
            np.int8, np.uint8, np.int16, np.uint16,
            np.int32, np.uint32, np.int64, np.uint64,
            np.float16, np.float32, np.float64,
            np.complex64, np.complex128,
        )

        def values(dtype, right: bool) -> np.ndarray:
            resolved = np.dtype(dtype)
            if np.issubdtype(resolved, np.complexfloating):
                source = (
                    [0.5 - 1.5j, -2.0 + 3.0j, 4.0 - 0.0j]
                    if right
                    else [1.0 + 2.0j, -3.0 + 0.5j, -0.0 - 1.0j]
                )
            elif np.issubdtype(resolved, np.bool_):
                source = [True, False, True]
            elif np.issubdtype(resolved, np.unsignedinteger):
                source = [2, 0, 3] if right else [1, 2, 0]
            else:
                source = [0.5, -1.5, 2.0] if right else [-2.0, 1.0, -0.0]
            return np.asarray(source, dtype=resolved)

        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            function = self._function(runtime)
            for left_dtype in dtypes:
                left_values = values(left_dtype, False)
                for right_dtype in dtypes:
                    right_values = values(right_dtype, True)
                    result_dtype = np.add(
                        left_values,
                        right_values,
                    ).dtype
                    with runtime.from_numpy(left_values) as left, runtime.from_numpy(
                        right_values
                    ) as right:
                        for output_dtype in dtypes:
                            initial = np.zeros(3, dtype=output_dtype)
                            expected = initial.copy()
                            can_cast = np.can_cast(
                                result_dtype,
                                output_dtype,
                                casting="same_kind",
                            )
                            if can_cast:
                                with np.errstate(invalid="ignore", over="ignore"):
                                    np.add(
                                        left_values,
                                        right_values,
                                        out=expected,
                                    )
                            with self.subTest(
                                left=str(left_values.dtype),
                                right=str(right_values.dtype),
                                output=str(np.dtype(output_dtype)),
                            ), runtime.from_numpy(initial) as output:
                                runtime.dll.cnp_clear_error()
                                status = function(
                                    left.pointer,
                                    right.pointer,
                                    output.pointer,
                                )
                                if can_cast:
                                    self.assertEqual(
                                        0,
                                        status,
                                        msg=str(runtime.error_state()),
                                    )
                                    AroundSemanticsTests._assert_matches_numpy(
                                        expected,
                                        output.to_numpy(),
                                    )
                                else:
                                    self.assertEqual(-3, status)
                                    error = runtime.error_state()
                                    self.assertEqual(
                                        "cnp_add_into",
                                        error.function,
                                    )
                                    self.assertIn(
                                        "same_kind",
                                        error.message,
                                    )
                                    self.assertEqual(
                                        initial.tobytes(),
                                        output.to_numpy().tobytes(),
                                    )
            self.assertEqual(baseline, runtime.retained_bytes)

