    def test_broadcasts_scalars_zero_length_dimensions_and_views(self) -> None:
        cases = (
            (
                np.asarray([[-1.0], [1.0]], dtype=np.float32),
                np.asarray([-1.0, 0.0, 1.0], dtype=np.float32),
            ),
            (
                np.asarray(-0.0, dtype=np.float64),
                np.asarray([[0.0, -0.0], [-1.0, 1.0]], dtype=np.float64),
            ),
            (
                np.zeros((0,), dtype=np.float16),
                np.ones((2, 1), dtype=np.float16),
            ),
        )
        with CnumpyRuntime(DLL) as runtime:
            baseline = runtime.retained_bytes
            for left_values, right_values in cases:
                with self.subTest(
                    left_shape=left_values.shape,
                    right_shape=right_values.shape,
                ):
                    expected = np.copysign(left_values, right_values)
                    with runtime.from_numpy(left_values) as left, runtime.from_numpy(
                        right_values
                    ) as right, self._call(runtime, left, right) as actual:
                        self.assertEqual(expected.shape, actual.shape)
                        self._assert_float_bits_equal(
                            actual.to_numpy(), expected
                        )

            base_values = np.asarray(
                [[-4.0, -1.0, -0.0], [0.0, 1.0, 4.0]],
                dtype=np.float32,
            )
            scalar_value = np.asarray(-1.0, dtype=np.float32)
            with runtime.from_numpy(base_values) as base, runtime.transpose(
                base, (1, 0)
            ) as left, runtime.from_numpy(scalar_value) as right, self._call(
                runtime, left, right
            ) as actual:
                expected = np.copysign(base_values.T, scalar_value)
                self.assertEqual(expected.shape, actual.shape)
                self.assertEqual(
                    expected.flags.c_contiguous, actual.c_contiguous
                )
                self.assertEqual(
                    expected.flags.f_contiguous, actual.f_contiguous
                )
                self._assert_float_bits_equal(actual.to_numpy(), expected)
            self.assertEqual(baseline, runtime.retained_bytes)

    def test_all_float16_patterns_match_numpy_125_for_both_signs(self) -> None:
        bits = np.arange(1 << 16, dtype=np.uint16)
